/**
 * Shared enum schemas — single source of truth for all domain enumerations.
 * Route schemas compose from these; client types derive via z.infer<>.
 */
import { z } from 'zod/v4';

// --- Bead ---
export const BeadStatus = z.enum([
  'pending', 'ready', 'in_progress', 'completed', 'blocked', 'failed', 'archived',
]);
export type BeadStatus = z.infer<typeof BeadStatus>;

export const BeadType = z.enum([
  'task', 'bug', 'feature', 'enhancement', 'thought', 'chore',
]);
export type BeadType = z.infer<typeof BeadType>;

// --- Job ---
export const JobStatus = z.enum([
  'queued', 'running', 'completed', 'failed', 'cancelled',
]);
export type JobStatus = z.infer<typeof JobStatus>;

export const JobType = z.enum(['execution', 'analysis', 'audit']);
export type JobType = z.infer<typeof JobType>;

export const WorkerType = z.enum(['docker', 'e2b', 'railway']);
export type WorkerType = z.infer<typeof WorkerType>;

// --- Project ---
export const AIProvider = z.enum(['claude', 'openai', 'openrouter']);
export type AIProvider = z.infer<typeof AIProvider>;

export const MergeStrategy = z.enum(['pr', 'direct']);
export type MergeStrategy = z.infer<typeof MergeStrategy>;

export const ProjectRole = z.enum(['owner', 'member', 'viewer', 'custom']);
export type ProjectRole = z.infer<typeof ProjectRole>;

export const ProjectPermission = z.enum([
  'manage_tasks', 'dispatch_agents', 'manage_memory',
]);
export type ProjectPermission = z.infer<typeof ProjectPermission>;

export const InitStatus = z.enum(['pending', 'running', 'completed', 'failed']);
export type InitStatus = z.infer<typeof InitStatus>;

// --- Notification ---
export const NotificationType = z.enum([
  'agent_complete', 'agent_failed', 'task_assigned', 'task_completed', 'system', 'info',
]);
export type NotificationType = z.infer<typeof NotificationType>;

// --- Activity ---
export const ActorType = z.enum(['user', 'agent', 'system']);
export type ActorType = z.infer<typeof ActorType>;

// --- Orchestration ---
export const PlanStatus = z.enum(['draft', 'active', 'completed']);
export type PlanStatus = z.infer<typeof PlanStatus>;

export const PlanItemStatus = z.enum(['pending', 'in_progress', 'completed', 'blocked']);
export type PlanItemStatus = z.infer<typeof PlanItemStatus>;

// --- Worktree ---
export const WorktreeRunStatus = z.enum(['running', 'completed', 'failed', 'cancelled']);
export type WorktreeRunStatus = z.infer<typeof WorktreeRunStatus>;

// --- Organization ---
export const OrgRole = z.enum(['owner', 'admin', 'member']);
export type OrgRole = z.infer<typeof OrgRole>;

// --- Team ---
export const TeamRole = z.enum(['lead', 'member']);
export type TeamRole = z.infer<typeof TeamRole>;

