/**
 * Step 3: Create notification helper — multi-user targeting
 *
 * Notifies: dispatcher, bead assignee, project owner (deduplicated).
 */
private async createNotification(
  job: AgentJob,
  type: 'agent_complete' | 'agent_failed',
  title: string,
  message: string,
  metadata?: Record<string, unknown>
): Promise<void> {
  try {
    const project = await projectOps.findById(job.projectId) as any;
    if (!project) return;

    // Load bead once — used for both title enrichment and assignee targeting
    const bead = job.beadId ? (await beadOps.findById(job.beadId) as any) : null;

    // Use bead.subject for a human-readable notification title; fall back to raw title
    // when no bead is linked (e.g. free-form jobs without a beadId).
    const notifTitle = bead?.subject ? `${title}: ${bead.subject}` : title;

    const enrichedMetadata = {
      jobId: job.id,
      ...(job.beadId ? { beadId: job.beadId } : {}),
      ...metadata,
    };
    const metadataJson = JSON.stringify(enrichedMetadata);

    // Collect target user IDs (deduplicated)
    const targetUserIds = new Set<string>();

    // 1. Project owner always gets notified
    targetUserIds.add(project.userId);

    // 2. Dispatcher (from dispatchedBy column)
    const freshJob = await agentJobOps.findById(job.id) as any;
    if (freshJob?.dispatchedBy) {
      targetUserIds.add(freshJob.dispatchedBy);
    }

    // 3. Bead assignee (if bead is loaded and has an assignee)
    if (bead?.assignedTo) {
      targetUserIds.add(bead.assignedTo);
    }

    // Send notification to each target user
    for (const userId of targetUserIds) {
      const id = `notif-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
      await notificationOps.create(
        id,
        userId,
        type,
        notifTitle,
        message || null,
        metadataJson,
        null, null, null
      );
    }

    // Emit SSE event for instant badge update
    projEvents.emit('change', { type: 'notifications:new', projectId: job.projectId });
  } catch (e) {
    console.warn('Failed to create notification:', e);
  }
}

/**
 * Build human-readable success message based on merge strategy
 */
private buildSuccessMessage(result: JobResult, mergeStrategy: 'pr' | 'direct'): string {
  const parts: string[] = [];

  if (result.summary) {
    parts.push(result.summary);
  }

  if (mergeStrategy === 'pr' && result.prUrl) {
    parts.push(`PR: ${result.prUrl}`);
  } else if (mergeStrategy === 'direct' && result.commitSha) {
    parts.push(`Pushed to ${result.branchName || 'branch'} (${result.commitSha.substring(0, 7)})`);
  }

  if (result.testResults?.ran) {
    parts.push(`Tests: ${result.testResults.summary}`);
  }

  if (result.filesChanged) {
    parts.push(`${result.filesChanged} file(s) changed`);
  }

  return parts.join('\n') || 'Agent completed successfully';

