/**
 * Typed chokepoint for creating notifications.
 *
 * Every creation site in the server should go through this helper rather than
 * calling `notificationOps.create()` directly. Two reasons:
 *
 * 1. **Compile-time metadata safety** — `MetadataFor<T>` narrows the metadata
 *    shape based on the supplied `type`, so a `task_assigned` notification
 *    can't accidentally be given an `agent_complete` payload and vice versa.
 *    See packages/api-types/src/schemas/notifications.ts for the shapes, and
 *    server/docs/notifications-contract.md for the human documentation.
 *
 * 2. **Single chokepoint for delivery concerns** — id generation, JSON
 *    stringification, and (in a future pass) SSE emission all happen here
 *    so individual call sites stay focused on the business event that
 *    triggered the notification.
 *
 * The low-level `notificationOps.create()` is still used by tests and DB
 * seeding helpers; it is not deprecated, but production code paths should
 * prefer this helper.
 */

import type { MetadataFor, NotificationType } from '@devdash/api-types';
import { notificationOps } from '../db/ops.js';

export interface EmitNotificationOpts<T extends NotificationType> {
  userId: string;
  type: T;
  title: string;
  message?: string | null;
  metadata: MetadataFor<T>;
  orgId?: string | null;
  projectId?: string | null;
  mentionType?: string | null;
}

/**
 * Persist a notification row with the correct metadata shape for its type.
 *
 * Returns the generated notification id so callers can reference it in
 * subsequent operations (e.g. SSE event correlation) if needed.
 */
export async function emitNotification<T extends NotificationType>(
  opts: EmitNotificationOpts<T>,
): Promise<string> {
  const id = `notif-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
  await notificationOps.create(
    id,
    opts.userId,
    opts.type,
    opts.title,
    opts.message ?? null,
    JSON.stringify(opts.metadata),
    opts.orgId ?? null,
    opts.projectId ?? null,
    opts.mentionType ?? null,
  );
  return id;
}

