import { requireProjectAccess, requirePermission } from '../middleware/project-access.js';
import { beadOps, beadCommentOps, userOps, notificationOps, projectOps } from '../db/ops.js';
import { projectEvents } from '../services/project-events.js';
import { logActivity } from '../services/activity-logger.js';
import { parseMentions, resolveMentionedUsers } from '../services/mention-parser.js';
import { utc } from '../utils/timestamps.js';
import { validate } from '../middleware/validate.js';
import { ListCommentsQuery, CreateCommentBody, UpdateCommentBody, DeleteCommentQuery } from '../schemas/index.js';

const router = Router();

router.use(requireAuth);

function formatComment(row: any, authorInfo?: any) {
  return {
    id: row.id,
    beadId: row.beadId,
    projectId: row.projectId,
    authorId: row.authorId,
    authorType: row.authorType,
    author: authorInfo || null,
    content: row.content,
    metadata: row.metadata ? JSON.parse(row.metadata) : null,
    createdAt: utc(row.createdAt as any),
    updatedAt: utc(row.updatedAt as any),
  };
}

/**
 * GET /api/beads/:beadId/comments?projectId=xxx - List comments for a bead
 */
router.get('/:beadId/comments', validate({ query: ListCommentsQuery }), async (req, res) => {
  try {
    const beadId = req.params.beadId as string;
    const { projectId } = req.query as unknown as ListCommentsQuery;
    const userId = (req.user as any).id;

    const project = requireProjectAccess(projectId, userId);
    if (!project) {
      return res.status(404).json({ error: 'Project not found' });
    }

    const bead = await beadOps.findById(beadId) as any;
    if (!bead || bead.projectId !== projectId) {
      return res.status(404).json({ error: 'Bead not found' });
    }

    const rows = await beadCommentOps.findByBeadId(beadId) as any[];

    // Enrich with author info
    const authorCache = new Map<string, any>();
    const data = [];
    for (const row of rows) {
      let author = null;
      if (row.authorId && row.authorType === 'user') {
        if (!authorCache.has(row.authorId)) {
          const user = await userOps.findById(row.authorId) as any;
          if (user) {
            authorCache.set(row.authorId, {
              id: user.id,
              displayName: user.displayName,
              avatarUrl: user.avatarUrl,
            });
          }
        }
        author = authorCache.get(row.authorId) || null;
      }
      data.push(formatComment(row, author));
    }

    res.json({ data });
  } catch (error) {
    console.error('Error listing comments:', error);
    res.status(500).json({ error: 'Failed to list comments' });
  }
});

/**
 * POST /api/beads/:beadId/comments - Create a comment on a bead
 */
router.post('/:beadId/comments', validate({ body: CreateCommentBody }), async (req, res) => {
  try {
    const beadId = req.params.beadId as string;
    const { projectId, content, metadata } = req.body as CreateCommentBody;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'manage_tasks');
    if (!project) {
      return res.status(403).json({ error: 'manage_tasks permission required' });
    }

    const bead = await beadOps.findById(beadId) as any;
    if (!bead || bead.projectId !== projectId) {
      return res.status(404).json({ error: 'Bead not found' });
    }

    const id = uuidv4();
    await beadCommentOps.create(
      id,
      beadId,
      projectId,
      userId,
      'user',
      content,
      metadata ? JSON.stringify(metadata) : null
    );

    const row = await beadCommentOps.findById(id) as any;
    const user = await userOps.findById(userId) as any;
    const author = user ? { id: user.id, displayName: user.displayName, avatarUrl: user.avatarUrl } : null;

    logActivity({
      projectId,
      actorId: userId,
      actorType: 'user',
      action: 'comment.created',
      targetType: 'bead',
      targetId: beadId,
      metadata: { commentId: id, beadSubject: bead.subject },
    });

    // Generate @mention notifications
    try {
      const usernames = parseMentions(content);
      if (usernames.length > 0) {
        const mentionedUserIds = await resolveMentionedUsers(usernames, projectId);
        const actorUser = await userOps.findById(userId) as any;
        const actorName = actorUser?.displayName || actorUser?.username || 'Someone';
        const proj = await projectOps.findById(projectId) as any;

        for (const mentionedId of mentionedUserIds) {
          if (mentionedId === userId) continue; // Don't notify yourself
          await emitNotification({
            userId: mentionedId,
            type: 'mention',
            title: `@${actorName} mentioned you in ${bead.subject}`,
            message: content.length > 200 ? content.slice(0, 200) + '...' : content,
            metadata: { beadId, commentId: id, projectId },
            orgId: proj?.orgId || null,
            projectId,
            mentionType: 'direct',
          });
        }
      }
    } catch (mentionErr) {
      console.warn('[Comments] Error generating mention notifications:', mentionErr);
    }

    projectEvents.emit('change', { type: 'comments:changed', projectId });
    res.status(201).json(formatComment(row, author));
  } catch (error) {
    console.error('Error creating comment:', error);
    res.status(500).json({ error: 'Failed to create comment' });
  }
});

/**
 * PATCH /api/beads/:beadId/comments/:commentId - Update a comment
 */
router.patch('/:beadId/comments/:commentId', validate({ body: UpdateCommentBody }), async (req, res) => {
  try {
    const beadId = req.params.beadId as string;
    const commentId = req.params.commentId as string;
    const { projectId, content } = req.body as UpdateCommentBody;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'manage_tasks');
    if (!project) {
      return res.status(403).json({ error: 'manage_tasks permission required' });
    }

    const comment = await beadCommentOps.findById(commentId) as any;
    if (!comment || comment.beadId !== beadId || comment.projectId !== projectId) {
      return res.status(404).json({ error: 'Comment not found' });
    }

    // Only author can edit their own comments
    if (comment.authorId !== userId) {
      return res.status(403).json({ error: 'You can only edit your own comments' });
    }

    await beadCommentOps.update(content, commentId);
    const row = await beadCommentOps.findById(commentId) as any;

    projectEvents.emit('change', { type: 'comments:changed', projectId });
    res.json(formatComment(row));
  } catch (error) {
    console.error('Error updating comment:', error);
    res.status(500).json({ error: 'Failed to update comment' });
  }
});

/**
 * DELETE /api/beads/:beadId/comments/:commentId - Delete a comment
 */
router.delete('/:beadId/comments/:commentId', validate({ query: DeleteCommentQuery }), async (req, res) => {
  try {
    const beadId = req.params.beadId as string;
    const commentId = req.params.commentId as string;
    const { projectId } = req.query as unknown as DeleteCommentQuery;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'manage_tasks');
    if (!project) {
      return res.status(403).json({ error: 'manage_tasks permission required' });
    }

    const comment = await beadCommentOps.findById(commentId) as any;
    if (!comment || comment.beadId !== beadId || comment.projectId !== projectId) {
      return res.status(404).json({ error: 'Comment not found' });
    }

    // Only author or project owner can delete
    if (comment.authorId !== userId && (project as any).userId !== userId) {
      return res.status(403).json({ error: 'You can only delete your own comments' });
    }

    await beadCommentOps.delete(commentId);

    projectEvents.emit('change', { type: 'comments:changed', projectId });
    res.status(204).send();
  } catch (error) {
    console.error('Error deleting comment:', error);
    res.status(500).json({ error: 'Failed to delete comment' });
  }
});

/**
 * Create an auto-generated system comment on a bead.
 * Used by agent-dispatch, bead assignment, etc.
 */
export async function createSystemComment(
  beadId: string,
  projectId: string,
  content: string,
  authorType: 'agent' | 'system' = 'system',
  authorId?: string,
  metadata?: Record<string, unknown>
): Promise<void> {
  try {
    const id = uuidv4();
    await beadCommentOps.create(
      id,
      beadId,
      projectId,
      authorId || null,
      authorType,
      content,
      metadata ? JSON.stringify(metadata) : null
    );
    projectEvents.emit('change', { type: 'comments:changed', projectId });
  } catch (e) {
    console.warn('[BeadComments] Failed to create system comment:', e);
  }
}

export default router;

