1	/**
2	 * Typed chokepoint for creating notifications.
3	 *
4	 * Every creation site in the server should go through this helper rather than
5	 * calling `notificationOps.create()` directly. Three reasons:
6	 *
7	 * 1. **Compile-time metadata safety** — `MetadataFor<T>` narrows the metadata
8	 *    shape based on the supplied `type`, so a `task_assigned` notification
9	 *    can't accidentally be given an `agent_complete` payload and vice versa.
10	 *    See packages/api-types/src/schemas/notifications.ts for the shapes, and
11	 *    server/docs/notifications-contract.md for the human documentation.
12	 *
13	 * 2. **Single chokepoint for delivery concerns** — id generation, JSON
14	 *    stringification, and SSE emission all happen here so individual call
15	 *    sites stay focused on the business event that triggered the notification.
16	 *
17	 * 3. **Real-time delivery via SSE** — after the row is persisted, the full
18	 *    notification payload is published on the project-events bus with the
19	 *    target `userId`. The /api/events SSE connection filter forwards it only
20	 *    to the matching user's open connections. See server/src/routes/events.ts
21	 *    and server/docs/notifications-contract.md.
22	 *
23	 * The low-level `notificationOps.create()` is still used by tests and DB
24	 * seeding helpers; it is not deprecated, but production code paths should
25	 * prefer this helper.
26	 */
27	
28	import type { Notification } from '@devdash/api-types';
29	import type { MetadataFor, NotificationType } from '../schemas/index.js';
30	import { notificationOps } from '../db/ops.js';
31	import { projectEvents } from '../services/project-events.js';
32	import { utc } from './timestamps.js';
33	
34	export interface EmitNotificationOpts<T extends NotificationType> {
35	  userId: string;
36	  type: T;
37	  title: string;
38	  message?: string | null;
39	  metadata: MetadataFor<T>;
40	  orgId?: string | null;
41	  projectId?: string | null;
42	  mentionType?: string | null;
43	}
44	
45	/**
46	 * Persist a notification row with the correct metadata shape for its type,
47	 * then publish a `notifications:new` SSE event carrying the full row.
48	 *
49	 * Returns the generated notification id so callers can reference it in
50	 * subsequent operations if needed.
51	 */
52	export async function emitNotification<T extends NotificationType>(
53	  opts: EmitNotificationOpts<T>,
54	): Promise<string> {
55	  const id = `notif-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
56	  const metadataJson = JSON.stringify(opts.metadata);
57	
58	  await notificationOps.create(
59	    id,
60	    opts.userId,
61	    opts.type,
62	    opts.title,
63	    opts.message ?? null,
64	    metadataJson,
65	    opts.orgId ?? null,
66	    opts.projectId ?? null,
67	    opts.mentionType ?? null,
68	  );
69	
70	  // Re-read the row so the SSE payload reflects DB-populated columns like
71	  // createdAt (which is set by the DB default, not the client). This keeps
72	  // the wire shape exactly aligned with the REST GET /api/notifications
73	  // response transform in server/src/routes/notifications.ts.
74	  try {
75	    const row = (await notificationOps.findById(id)) as any;
76	    if (row) {
77	      const notification: Notification = {
78	        id: row.id,
79	        userId: row.userId,
80	        type: row.type,
81	        title: row.title,
82	        message: row.message,
83	        read: Boolean(row.read),
84	        dismissed: Boolean(row.dismissed),
85	        metadata: row.metadata ? JSON.parse(row.metadata) : null,
86	        createdAt: utc(row.createdAt),
87	      };
88	
89	      projectEvents.emit('change', {
90	        type: 'notifications:new',
91	        projectId: opts.projectId ?? '',
92	        userId: opts.userId,
93	        notification,
94	      });
95	    }
96	  } catch (e) {
97	    // SSE publication is best-effort. The row is already persisted; worst
98	    // case the client picks it up on next reconnect-gap REST refetch.
99	    console.warn('[emitNotification] SSE publish failed:', e);
100	  }
101	
102	  return id;
103	}

