/**
 * Click-through target derivation for notifications.
 *
 * Single source of truth for turning a `Notification` into a navigable target.
 * Both the bell dropdown (NotificationBell) and the full-page notifications list
 * (pages/Notifications) import from here so the two UIs stay in lockstep.
 *
 * The per-type rules follow `server/docs/notifications-contract.md`.
 *
 * This module is intentionally UI-agnostic: it returns plain href strings and
 * does NOT call `useNavigate()` or touch any router. Call sites render
 * `<a href={target.href}>` so Cmd/Ctrl-click opens in a new tab.
 */
import type {
  Notification,
  AgentCompleteMetadata,
  AgentFailedMetadata,
  TaskAssignedMetadata,
  MentionMetadata,
} from '@devdash/api-types';

export type ClickTarget =
  | { kind: 'internal'; href: string }
  | { kind: 'external'; href: string }
  | { kind: 'none' };

/**
 * Optional context the caller may pass in so we can resolve targets that
 * require data not carried on the notification metadata itself (e.g. the
 * `owner/repo` slug for an external GitHub rescue-branch link).
 */
export interface ClickTargetContext {
  /**
   * Map of projectId -> githubRepo slug (e.g. `"owner/repo"`).
   * Used to resolve external GitHub URLs for `agent_failed.rescueBranch` and
   * `agent_complete.prUrl` when the URL isn't fully qualified.
   */
  projectRepos?: Record<string, string | undefined>;
}

// ---------------------------------------------------------------------------
// Internal route helpers
// ---------------------------------------------------------------------------

/**
 * Build the internal href for a bead detail view.
 *
 * The dev-dash main UI does not (yet) have a dedicated `/beads/:id` route —
 * beads are opened as modals from inside the project's Beads tab. We deep-link
 * via query params on the project page so the target remains a normal URL
 * (supports new-tab, back button, bookmarking) and a future enhancement to
 * BeadsList can read `?bead=<id>` and auto-open the modal.
 *
 * If `projectId` is missing we fall back to `/dashboard`, since we have no way
 * to know which project the bead lives in.
 */
function beadHref(projectId: string | undefined, beadId: string, anchor?: string): string {
  if (!projectId) return '/dashboard';
  const base = `/project/${projectId}?tab=beads&bead=${encodeURIComponent(beadId)}`;
  return anchor ? `${base}#${anchor}` : base;
}

/**
 * Build an external GitHub branch URL from a `owner/repo` slug and a branch name.
 * Returns `null` if we can't produce a valid URL.
 */
function githubBranchUrl(repoSlug: string | undefined, branch: string): string | null {
  if (!repoSlug) return null;
  // Accept either `owner/repo` or a full URL — normalize to the slug.
  const slug = repoSlug.replace(/^https?:\/\/github\.com\//, '').replace(/\.git$/, '');
  if (!slug.includes('/')) return null;
  return `https://github.com/${slug}/tree/${encodeURIComponent(branch)}`;
}

// ---------------------------------------------------------------------------
// Primary: deriveClickTarget
// ---------------------------------------------------------------------------

export function deriveClickTarget(
  notification: Notification,
  ctx: ClickTargetContext = {},
): ClickTarget {
  const md = (notification.metadata ?? {}) as Record<string, unknown>;

  switch (notification.type) {
    case 'agent_complete': {
      const m = md as Partial<AgentCompleteMetadata>;
      // Primary action is always the bead (PR gets surfaced as a secondary
      // action — see `deriveSecondaryAction` below). If no bead, fall through
      // to the PR if we have one, else no-op.
      if (m.beadId) {
        return { kind: 'internal', href: beadHref(m.projectId, m.beadId) };
      }
      if (m.prUrl) {
        return { kind: 'external', href: m.prUrl };
      }
      return { kind: 'none' };
    }

    case 'agent_failed': {
      const m = md as Partial<AgentFailedMetadata>;
      // Rescue branch on GitHub wins ONLY when there's no bead — otherwise the
      // bead is the primary and the rescue branch gets surfaced as a secondary
      // action. This keeps the "navigate to the thing you work in" rule
      // consistent across all agent_* notifications.
      if (m.beadId) {
        return { kind: 'internal', href: beadHref(m.projectId, m.beadId) };
      }
      if (m.rescueBranch && m.projectId) {
        const url = githubBranchUrl(ctx.projectRepos?.[m.projectId], m.rescueBranch);
        if (url) return { kind: 'external', href: url };
      }
      return { kind: 'none' };
    }

    case 'task_assigned': {
      const m = md as Partial<TaskAssignedMetadata>;
      if (m.beadId) {
        return { kind: 'internal', href: beadHref(m.projectId, m.beadId) };
      }
      return { kind: 'none' };
    }

    case 'mention': {
      const m = md as Partial<MentionMetadata>;
      if (m.beadId) {
        const anchor = m.commentId ? `comment-${m.commentId}` : undefined;
        return { kind: 'internal', href: beadHref(m.projectId, m.beadId, anchor) };
      }
      return { kind: 'none' };
    }

    case 'task_completed':
    case 'system':
    case 'info':
    default:
      return { kind: 'none' };
  }
}

// ---------------------------------------------------------------------------
// Optional: deriveSecondaryAction
// ---------------------------------------------------------------------------

/**
 * Some notification types benefit from a second click target alongside the
 * primary one (e.g. `agent_complete` with a PR: the main row opens the bead,
 * and a secondary button opens the PR on GitHub in a new tab).
 *
 * Returns `null` when there is no meaningful secondary action.
 */
export interface SecondaryAction {
  kind: 'external';
  href: string;
  label: string; // human-readable, for the button/aria-label
  icon: 'pr' | 'branch';
}

export function deriveSecondaryAction(
  notification: Notification,
  ctx: ClickTargetContext = {},
): SecondaryAction | null {
  const md = (notification.metadata ?? {}) as Record<string, unknown>;

  if (notification.type === 'agent_complete') {
    const m = md as Partial<AgentCompleteMetadata>;
    // Only surface the PR as a secondary action if the PRIMARY target was the
    // bead (otherwise `deriveClickTarget` already points at the PR itself).
    if (m.beadId && m.prUrl) {
      return { kind: 'external', href: m.prUrl, label: 'Open pull request', icon: 'pr' };
    }
    return null;
  }

  if (notification.type === 'agent_failed') {
    const m = md as Partial<AgentFailedMetadata>;
    if (m.beadId && m.rescueBranch && m.projectId) {
      const url = githubBranchUrl(ctx.projectRepos?.[m.projectId], m.rescueBranch);
      if (url) return { kind: 'external', href: url, label: 'Open rescue branch', icon: 'branch' };
    }
    return null;
  }

  return null;
}

