@@ -0,0 +1,81 @@
+/**
+ * Notifications Cleanup — periodic prune of stale notifications across all users.
+ *
+ * The notifications table grows unbounded otherwise. Retention is hardcoded
+ * (90 days) per the notifications-prefs-client-side decision — any user-visible
+ * retention/filtering preferences live client-side.
+ *
+ * Runs daily. Executes a single global DELETE (no per-user fan-out) and logs
+ * how many rows were pruned.
+ */
+
+import { notificationOps } from '../db/ops.js';
+
+const TAG = '[NotificationsCleanup]';
+
+/** Retention window — hardcoded. Do NOT add a config surface. */
+const RETENTION_INTERVAL = '90 days';
+
+/** Run cadence. Daily is plenty for a cleanup job; the table is append-only. */
+const RUN_INTERVAL_MS = 24 * 60 * 60 * 1000;
+
+/** Delay before the first run so startup isn't slowed by a DELETE. */
+const INITIAL_DELAY_MS = 5 * 60 * 1000;
+
+class NotificationsCleanupService {
+  private timer: NodeJS.Timeout | null = null;
+  private initialTimer: NodeJS.Timeout | null = null;
+
+  start(): void {
+    if (this.timer || this.initialTimer) return;
+
+    // Defer the first run a few minutes so boot isn't blocked on a DELETE.
+    this.initialTimer = setTimeout(() => {
+      this.initialTimer = null;
+      void this.run();
+      this.timer = setInterval(() => void this.run(), RUN_INTERVAL_MS);
+    }, INITIAL_DELAY_MS);
+
+    console.log(
+      `${TAG} Started (retention: ${RETENTION_INTERVAL}, cadence: ${RUN_INTERVAL_MS / 3_600_000}h, first run in ${INITIAL_DELAY_MS / 60_000}m)`
+    );
+  }
+
+  stop(): void {
+    if (this.initialTimer) {
+      clearTimeout(this.initialTimer);
+      this.initialTimer = null;
+    }
+    if (this.timer) {
+      clearInterval(this.timer);
+      this.timer = null;
+      console.log(`${TAG} Stopped`);
+    }
+  }
+
+  /**
+   * Execute a single cleanup pass. Exposed for tests / manual invocation.
+   * Returns the number of rows pruned (best-effort — falls back to 0 if the
+   * driver doesn't surface a rowCount).
+   */
+  async run(): Promise<number> {
+    const startedAt = Date.now();
+    try {
+      const result = (await notificationOps.deleteOldGlobal(RETENTION_INTERVAL)) as unknown as {
+        rowCount?: number | null;
+        rowsAffected?: number | null;
+      };
+      const pruned = result?.rowCount ?? result?.rowsAffected ?? 0;
+      const durationMs = Date.now() - startedAt;
+      console.log(
+        `${TAG} Pruned ${pruned} notification(s) older than ${RETENTION_INTERVAL} in ${durationMs}ms`
+      );
+      return pruned ?? 0;
+    } catch (err) {
+      console.error(`${TAG} Cleanup failed:`, err);
+      return 0;
+    }
+  }
+}
+
+export const notificationsCleanup = new NotificationsCleanupService();

