/**
 * Notifications SSE / emitNotification chokepoint tests
 *
 * Covers the server-side real-time delivery path from dd 03ab1f97:
 * emitNotification() must persist the row and then publish a notifications:new
 * event carrying the full wire-format Notification. Publication is best-effort
 * and must not roll back the row on failure.
 *
 * HTTP-level SSE scoping in routes/events.ts is NOT tested here — supertest
 * doesn't play well with long-lived streams, and the filter logic is simple
 * enough that we trust the code review. If that gap bites, file a follow-up.
 */

import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';
import { setupTestApp, type TestContext } from './test-app.js';
import { notificationOps } from '../db/ops.js';
import { projectEvents, type ProjectEvent } from '../services/project-events.js';
import { emitNotification } from '../utils/emit-notification.js';
import type { Notification } from '@devdash/api-types';

let ctx: TestContext;

beforeAll(async () => {
  ctx = await setupTestApp();
});

afterAll(async () => {
  await ctx?.cleanup();
});

/** Capture a single notifications:new event published during `fn()`. */
async function captureNotificationEvent(
  fn: () => Promise<unknown>,
): Promise<ProjectEvent | null> {
  let captured: ProjectEvent | null = null;
  const listener = (event: ProjectEvent) => {
    if (event.type === 'notifications:new') {
      captured = event;
    }
  };
  projectEvents.on('change', listener);
  try {
    await fn();
  } finally {
    projectEvents.removeListener('change', listener);
  }
  return captured;
}

describe('emitNotification chokepoint', () => {
  it('persists a row AND publishes a notifications:new event', async () => {
    const event = await captureNotificationEvent(() =>
      emitNotification({
        userId: ctx.userId,
        type: 'task_assigned',
        title: 'Assigned to you: Test bead',
        metadata: {
          beadId: 'bead-test-1',
          projectId: ctx.projectId,
          assignedBy: 'user-actor',
        },
      }),
    );

    expect(event).toBeTruthy();
    expect(event!.type).toBe('notifications:new');
    expect(event!.userId).toBe(ctx.userId);
    expect(event!.notification).toBeTruthy();

    const notif = event!.notification!;
    expect(notif.userId).toBe(ctx.userId);
    expect(notif.type).toBe('task_assigned');
    expect(notif.title).toBe('Assigned to you: Test bead');
    // New rows are always read:false, dismissed:false (sanity check for the
    // dismissed-state migration)
    expect(notif.read).toBe(false);
    expect(notif.dismissed).toBe(false);
    // Metadata is parsed on the wire, not the raw JSON string
    expect(notif.metadata).toEqual({
      beadId: 'bead-test-1',
      projectId: ctx.projectId,
      assignedBy: 'user-actor',
    });
    // The row should exist in the DB with the same id the event carries
    const row = (await notificationOps.findById(notif.id)) as any;
    expect(row).toBeTruthy();
    expect(row.id).toBe(notif.id);
    expect(Boolean(row.read)).toBe(false);
    expect(Boolean(row.dismissed)).toBe(false);
  });

  it('emits the projectId the caller supplied (and empty string when absent)', async () => {
    // Caller passes projectId → event carries it
    const withProj = await captureNotificationEvent(() =>
      emitNotification({
        userId: ctx.userId,
        type: 'task_assigned',
        title: 'With project',
        metadata: {
          beadId: 'bead-test-2',
          projectId: ctx.projectId,
        },
        projectId: ctx.projectId,
      }),
    );
    expect(withProj?.projectId).toBe(ctx.projectId);

    // Caller omits projectId (e.g. a system-level notification) → event carries ''
    // and the filter in events.ts still routes by userId, so no leak.
    const withoutProj = await captureNotificationEvent(() =>
      emitNotification({
        userId: ctx.userId,
        type: 'info',
        title: 'System-level notification',
        metadata: { reason: 'boot' },
      }),
    );
    expect(withoutProj?.projectId).toBe('');
    expect(withoutProj?.userId).toBe(ctx.userId);
  });

  it('persists the row even when SSE publish throws (best-effort)', async () => {
    // Force projectEvents.emit to throw once
    const emitSpy = vi.spyOn(projectEvents, 'emit').mockImplementationOnce(() => {
      throw new Error('simulated SSE bus failure');
    });

    let id: string;
    try {
      id = await emitNotification({
        userId: ctx.userId,
        type: 'agent_complete',
        title: 'Completed despite bus failure',
        metadata: {
          jobId: 'job-test-sse-fail',
          projectId: ctx.projectId,
        },
      });
    } finally {
      emitSpy.mockRestore();
    }

    // Row must still be persisted
    const row = (await notificationOps.findById(id)) as any;
    expect(row).toBeTruthy();
    expect(row.type).toBe('agent_complete');
    expect(row.title).toBe('Completed despite bus failure');
  });

  it('enforces metadata shape per type at compile time', async () => {
    // This test is really a compile-time assertion wrapped in a runtime smoke
    // test. If MetadataFor<T> ever stops narrowing, the types below won't match
    // the per-type schemas and tsc will fail before the test even runs.

    await emitNotification({
      userId: ctx.userId,
      type: 'agent_complete',
      title: 'Agent succeeded',
      metadata: {
        jobId: 'job-a',
        beadId: 'bead-a',
        projectId: ctx.projectId,
        prUrl: 'https://github.com/owner/repo/pull/1',
        commitSha: 'deadbeef',
        branchName: 'feat/test',
      },
    });

    await emitNotification({
      userId: ctx.userId,
      type: 'agent_failed',
      title: 'Agent failed',
      metadata: {
        jobId: 'job-b',
        projectId: ctx.projectId,
        rescueBranch: 'rescue/job-b',
      },
    });

    await emitNotification({
      userId: ctx.userId,
      type: 'mention',
      title: '@alice mentioned you',
      metadata: {
        beadId: 'bead-c',
        commentId: 'comment-c',
        projectId: ctx.projectId,
      },
    });

    // If we got here, the narrowings all held. No runtime assertion needed
    // beyond "no exception was thrown".
    expect(true).toBe(true);
  });

  it('published notification wire shape matches GET /api/notifications transform', async () => {
    // The SSE payload must be drop-in compatible with what the REST endpoint
    // returns, so clients can union the two code paths without type gymnastics.
    const event = await captureNotificationEvent(() =>
      emitNotification({
        userId: ctx.userId,
        type: 'mention',
        title: 'Wire shape check',
        message: 'body',
        metadata: {
          beadId: 'bead-wire',
          commentId: 'comment-wire',
          projectId: ctx.projectId,
        },
      }),
    );

    const notif = event!.notification as Notification;
    // Every field on the Notification interface must be present and typed
    expect(typeof notif.id).toBe('string');
    expect(typeof notif.userId).toBe('string');
    expect(typeof notif.type).toBe('string');
    expect(typeof notif.title).toBe('string');
    expect(notif.message === null || typeof notif.message === 'string').toBe(true);
    expect(typeof notif.read).toBe('boolean');
    expect(typeof notif.dismissed).toBe('boolean');
    expect(notif.metadata === null || typeof notif.metadata === 'object').toBe(true);
    expect(typeof notif.createdAt).toBe('string');
    // createdAt should be an ISO string (parseable)
    expect(Number.isNaN(Date.parse(notif.createdAt))).toBe(false);
  });
});

