        title: 'With project',
        metadata: {
          beadId: 'bead-test-2',
          projectId: ctx.projectId,
        },
        projectId: ctx.projectId,
      }),
    );
    expect(withProj?.projectId).toBe(ctx.projectId);

    // Caller omits projectId (e.g. a system-level notification) → event carries ''
    // and the filter in events.ts still routes by userId, so no leak.
    const withoutProj = await captureNotificationEvent(() =>
      emitNotification({
        userId: ctx.userId,
        type: 'info',
        title: 'System-level notification',
        metadata: { reason: 'boot' },
      }),
    );
    expect(withoutProj?.projectId).toBe('');
    expect(withoutProj?.userId).toBe(ctx.userId);
  });

  it('persists the row even when SSE publish throws (best-effort)', async () => {
    // Force projectEvents.emit to throw once
    const emitSpy = vi.spyOn(projectEvents, 'emit').mockImplementationOnce(() => {
      throw new Error('simulated SSE bus failure');
    });

    let id: string;
    try {
      id = await emitNotification({
        userId: ctx.userId,
        type: 'agent_complete',
        title: 'Completed despite bus failure',
        metadata: {
          jobId: 'job-test-sse-fail',
          projectId: ctx.projectId,
        },
      });
    } finally {
      emitSpy.mockRestore();
    }

    // Row must still be persisted
    const row = (await notificationOps.findById(id)) as any;
    expect(row).toBeTruthy();
    expect(row.type).toBe('agent_complete');
    expect(row.title).toBe('Completed despite bus failure');
  });

  it('enforces metadata shape per type at compile time', async () => {
    // This test is really a compile-time assertion wrapped in a runtime smoke
    // test. If MetadataFor<T> ever stops narrowing, the types below won't match
    // the per-type schemas and tsc will fail before the test even runs.

    await emitNotification({
      userId: ctx.userId,
      type: 'agent_complete',
      title: 'Agent succeeded',
      metadata: {
        jobId: 'job-a',
        beadId: 'bead-a',
        projectId: ctx.projectId,
        prUrl: 'https://github.com/owner/repo/pull/1',
        commitSha: 'deadbeef',
        branchName: 'feat/test',
      },
    });

    await emitNotification({
      userId: ctx.userId,
      type: 'agent_failed',
      title: 'Agent failed',
      metadata: {
        jobId: 'job-b',
        projectId: ctx.projectId,
        rescueBranch: 'rescue/job-b',
      },
    });

    await emitNotification({
      userId: ctx.userId,
      type: 'mention',
      title: '@alice mentioned you',
      metadata: {
        beadId: 'bead-c',
        commentId: 'comment-c',
        projectId: ctx.projectId,
      },
    });

    // If we got here, the narrowings all held. No runtime assertion needed
    // beyond "no exception was thrown".
    expect(true).toBe(true);
  });

  it('published notification wire shape matches GET /api/notifications transform', async () => {
    // The SSE payload must be drop-in compatible with what the REST endpoint
    // returns, so clients can union the two code paths without type gymnastics.
    const event = await captureNotificationEvent(() =>
      emitNotification({
        userId: ctx.userId,
        type: 'mention',
        title: 'Wire shape check',
        message: 'body',
        metadata: {
          beadId: 'bead-wire',
          commentId: 'comment-wire',
          projectId: ctx.projectId,
        },
      }),
    );

    const notif = event!.notification as Notification;
    // Every field on the Notification interface must be present and typed
    expect(typeof notif.id).toBe('string');
    expect(typeof notif.userId).toBe('string');
    expect(typeof notif.type).toBe('string');
    expect(typeof notif.title).toBe('string');
    expect(notif.message === null || typeof notif.message === 'string').toBe(true);
    expect(typeof notif.read).toBe('boolean');
    expect(typeof notif.dismissed).toBe('boolean');
    expect(notif.metadata === null || typeof notif.metadata === 'object').toBe(true);
    expect(typeof notif.createdAt).toBe('string');
    // createdAt should be an ISO string (parseable)
    expect(Number.isNaN(Date.parse(notif.createdAt))).toBe(false);
  });
});

