/**
 * Unit tests for deriveClickTarget + deriveSecondaryAction.
 *
 * Pure function tests — no React, no router, no DOM. Covers every per-type
 * branch from server/docs/notifications-contract.md plus edge cases for
 * external-link resolution via ClickTargetContext.projectRepos.
 */

import { describe, it, expect } from 'vitest';
import {
  deriveClickTarget,
  deriveSecondaryAction,
  type ClickTargetContext,
} from './deriveClickTarget';
import type { Notification, NotificationType } from '@devdash/api-types';

/** Build a Notification fixture for tests. */
function notif(
  type: NotificationType,
  metadata: Record<string, unknown>,
  overrides: Partial<Notification> = {},
): Notification {
  return {
    id: 'notif-test',
    userId: 'user-test',
    type,
    title: 'test',
    message: null,
    read: false,
    dismissed: false,
    metadata,
    createdAt: '2026-04-11T00:00:00.000Z',
    ...overrides,
  };
}

const PROJECT_ID = 'proj-abc';
const BEAD_ID = 'bead-xyz';
const COMMENT_ID = 'comment-123';
const REPO_SLUG = 'owner/repo';

const ctxWithRepo: ClickTargetContext = {
  projectRepos: { [PROJECT_ID]: REPO_SLUG },
};

// ---------------------------------------------------------------------------
// deriveClickTarget — per type
// ---------------------------------------------------------------------------

describe('deriveClickTarget', () => {
  describe('agent_complete', () => {
    it('routes to the bead when beadId is present', () => {
      const target = deriveClickTarget(
        notif('agent_complete', {
          jobId: 'j1',
          beadId: BEAD_ID,
          projectId: PROJECT_ID,
          prUrl: 'https://github.com/owner/repo/pull/1',
        }),
      );
      expect(target).toEqual({
        kind: 'internal',
        href: `/project/${PROJECT_ID}?tab=beads&bead=${BEAD_ID}`,
      });
    });

    it('falls back to the PR URL when there is no bead', () => {
      const target = deriveClickTarget(
        notif('agent_complete', {
          jobId: 'j1',
          prUrl: 'https://github.com/owner/repo/pull/42',
        }),
      );
      expect(target).toEqual({
        kind: 'external',
        href: 'https://github.com/owner/repo/pull/42',
      });
    });

    it('returns none when there is neither bead nor PR', () => {
      const target = deriveClickTarget(notif('agent_complete', { jobId: 'j1' }));
      expect(target).toEqual({ kind: 'none' });
    });
  });

  describe('agent_failed', () => {
    it('routes to the bead when beadId is present, even if there is a rescue branch', () => {
      const target = deriveClickTarget(
        notif('agent_failed', {
          jobId: 'j2',
          beadId: BEAD_ID,
          projectId: PROJECT_ID,
          rescueBranch: 'rescue/j2',
        }),
        ctxWithRepo,
      );
      expect(target).toEqual({
        kind: 'internal',
        href: `/project/${PROJECT_ID}?tab=beads&bead=${BEAD_ID}`,
      });
    });

    it('routes to the GitHub rescue branch when there is no bead but context has a repo', () => {
      const target = deriveClickTarget(
        notif('agent_failed', {
          jobId: 'j3',
          projectId: PROJECT_ID,
          rescueBranch: 'rescue/j3',
        }),
        ctxWithRepo,
      );
      expect(target).toEqual({
        kind: 'external',
        href: `https://github.com/${REPO_SLUG}/tree/${encodeURIComponent('rescue/j3')}`,
      });
    });

    it('degrades to none when a rescue branch has no repo in the context', () => {
      const target = deriveClickTarget(
        notif('agent_failed', {
          jobId: 'j4',
          projectId: PROJECT_ID,
          rescueBranch: 'rescue/j4',
        }),
        // No projectRepos entry for this project
        {},
      );
      expect(target).toEqual({ kind: 'none' });
    });

    it('returns none when there is nothing to link to', () => {
      const target = deriveClickTarget(notif('agent_failed', { jobId: 'j5' }));
      expect(target).toEqual({ kind: 'none' });
    });
  });

  describe('task_assigned', () => {
    it('routes to the bead', () => {
      const target = deriveClickTarget(
        notif('task_assigned', {
          beadId: BEAD_ID,
          projectId: PROJECT_ID,
          assignedBy: 'actor',
        }),
      );
      expect(target).toEqual({
        kind: 'internal',
        href: `/project/${PROJECT_ID}?tab=beads&bead=${BEAD_ID}`,
      });
    });

    it('returns none when metadata is malformed (no beadId)', () => {
      const target = deriveClickTarget(notif('task_assigned', { projectId: PROJECT_ID }));
      expect(target).toEqual({ kind: 'none' });
    });
  });

  describe('mention', () => {
    it('routes to the bead with a comment anchor', () => {
      const target = deriveClickTarget(
        notif('mention', {
          beadId: BEAD_ID,
          commentId: COMMENT_ID,
          projectId: PROJECT_ID,
        }),
      );
      expect(target).toEqual({
        kind: 'internal',
        href: `/project/${PROJECT_ID}?tab=beads&bead=${BEAD_ID}#comment-${COMMENT_ID}`,
      });
    });

    it('omits the anchor when commentId is missing', () => {
      const target = deriveClickTarget(
        notif('mention', { beadId: BEAD_ID, projectId: PROJECT_ID }),
      );
      expect(target).toEqual({
        kind: 'internal',
        href: `/project/${PROJECT_ID}?tab=beads&bead=${BEAD_ID}`,
      });
    });
  });

  describe('reserved types', () => {
    it.each(['task_completed', 'system', 'info'] as const)(
      'returns none for %s',
      (type) => {
        expect(deriveClickTarget(notif(type, {}))).toEqual({ kind: 'none' });
      },
    );
  });

  describe('edge cases — bead href construction', () => {
    it('falls back to /dashboard when projectId is missing', () => {
      // agent_complete does not require projectId in its metadata, so the
      // helper's beadHref() fallback is reachable.
      const target = deriveClickTarget(
        notif('agent_complete', { jobId: 'j1', beadId: BEAD_ID }),
      );
      expect(target).toEqual({ kind: 'internal', href: '/dashboard' });
    });

    it('URL-encodes bead IDs that contain special characters', () => {
      const target = deriveClickTarget(
        notif('task_assigned', {
          beadId: 'bead/with slash',
          projectId: PROJECT_ID,
        }),
      );
      expect(target.kind).toBe('internal');
      expect((target as { kind: 'internal'; href: string }).href).toBe(
        `/project/${PROJECT_ID}?tab=beads&bead=${encodeURIComponent('bead/with slash')}`,
      );
    });
  });

  describe('edge cases — github branch URL', () => {
    it('accepts a full https://github.com URL as the repo slug', () => {
      const target = deriveClickTarget(
        notif('agent_failed', {
          jobId: 'j6',
          projectId: PROJECT_ID,
          rescueBranch: 'rescue/j6',
        }),
        { projectRepos: { [PROJECT_ID]: 'https://github.com/owner/repo.git' } },
      );
      expect(target).toEqual({
        kind: 'external',
        href: `https://github.com/owner/repo/tree/${encodeURIComponent('rescue/j6')}`,
      });
    });

    it('rejects malformed slugs without a slash', () => {
      const target = deriveClickTarget(
        notif('agent_failed', {
          jobId: 'j7',
          projectId: PROJECT_ID,
          rescueBranch: 'rescue/j7',
        }),
        { projectRepos: { [PROJECT_ID]: 'notaslug' } },
      );
      expect(target).toEqual({ kind: 'none' });
    });

    it('URL-encodes branch names with slashes', () => {
      const target = deriveClickTarget(
        notif('agent_failed', {
          jobId: 'j8',
          projectId: PROJECT_ID,
          rescueBranch: 'feature/sub-branch',
        }),
        ctxWithRepo,
      );
      expect(target).toEqual({
        kind: 'external',
        href: `https://github.com/${REPO_SLUG}/tree/${encodeURIComponent('feature/sub-branch')}`,
      });
    });
  });
});

// ---------------------------------------------------------------------------
// deriveSecondaryAction — per type
// ---------------------------------------------------------------------------

describe('deriveSecondaryAction', () => {
  describe('agent_complete', () => {
    it('returns a PR secondary action when primary is the bead and PR is present', () => {
      const action = deriveSecondaryAction(
        notif('agent_complete', {
          jobId: 'j1',
          beadId: BEAD_ID,
          projectId: PROJECT_ID,
          prUrl: 'https://github.com/owner/repo/pull/1',
        }),
      );
      expect(action).toEqual({
        kind: 'external',
        href: 'https://github.com/owner/repo/pull/1',
        label: 'Open pull request',
        icon: 'pr',
      });
    });

    it('returns null when there is no bead (PR is already the primary target)', () => {
      const action = deriveSecondaryAction(
        notif('agent_complete', {
          jobId: 'j1',
          prUrl: 'https://github.com/owner/repo/pull/1',
        }),
      );
      expect(action).toBeNull();
    });

    it('returns null when there is no PR', () => {
      const action = deriveSecondaryAction(
        notif('agent_complete', {
          jobId: 'j1',
          beadId: BEAD_ID,
          projectId: PROJECT_ID,
        }),
      );
      expect(action).toBeNull();
    });
  });

  describe('agent_failed', () => {
    it('returns a rescue-branch secondary action when primary is the bead and rescue is present', () => {
      const action = deriveSecondaryAction(
        notif('agent_failed', {
          jobId: 'j2',
          beadId: BEAD_ID,
          projectId: PROJECT_ID,
          rescueBranch: 'rescue/j2',
        }),
        ctxWithRepo,
      );
      expect(action).toEqual({
        kind: 'external',
        href: `https://github.com/${REPO_SLUG}/tree/${encodeURIComponent('rescue/j2')}`,
        label: 'Open rescue branch',
        icon: 'branch',
      });
    });

    it('returns null when there is no bead (rescue branch would be the primary target)', () => {
      const action = deriveSecondaryAction(
        notif('agent_failed', {
          jobId: 'j3',
          projectId: PROJECT_ID,
          rescueBranch: 'rescue/j3',
        }),
        ctxWithRepo,
      );
      expect(action).toBeNull();
    });

    it('returns null when context cannot resolve the repo slug', () => {
      const action = deriveSecondaryAction(
        notif('agent_failed', {
          jobId: 'j4',
          beadId: BEAD_ID,
          projectId: PROJECT_ID,
          rescueBranch: 'rescue/j4',
        }),
        {},
      );
      expect(action).toBeNull();
    });
  });

  describe('other types have no secondary action', () => {
    it.each([
      ['task_assigned', { beadId: BEAD_ID, projectId: PROJECT_ID }],
      ['mention', { beadId: BEAD_ID, commentId: COMMENT_ID, projectId: PROJECT_ID }],
      ['task_completed', {}],
      ['system', {}],
      ['info', {}],
    ] as const)('returns null for %s', (type, metadata) => {
      expect(deriveSecondaryAction(notif(type, metadata))).toBeNull();
    });
  });
});

