/**
 * Notifications SSE / emitNotification chokepoint tests
 *
 * Covers the server-side real-time delivery path from dd 03ab1f97:
 * emitNotification() must persist the row and then publish a notifications:new
 * event carrying the full wire-format Notification. Publication is best-effort
 * and must not roll back the row on failure.
 *
 * The DB layer is mocked here — the round-trip is already covered by
 * `ops-smoke.test.ts`. This file verifies the helper's emit logic in isolation
 * so it runs without a local Postgres.
 *
 * HTTP-level SSE scoping in routes/events.ts is NOT tested here — supertest
 * doesn't play well with long-lived streams, and the filter logic is simple
 * enough that we trust the code review. File a follow-up if that gap bites.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';

// Mock the DB ops BEFORE importing the helper so it picks up the mocks.
// `emit-notification` calls `notificationOps.create` and `notificationOps.findById`.
vi.mock('../db/ops.js', () => {
  const rows = new Map<string, any>();
  return {
    notificationOps: {
      create: vi.fn(
        (
          id: string,
          userId: string,
          type: string,
          title: string,
          message: string | null,
          metadata: string | null,
          orgId: string | null,
          projectId: string | null,
          mentionType: string | null,
        ) => {
          rows.set(id, {
            id,
            userId,
            type,
            title,
            message,
            read: false,
            dismissed: false,
            metadata,
            orgId,
            projectId,
            mentionType,
            createdAt: new Date('2026-04-11T00:00:00.000Z'),
          });
          return Promise.resolve();
        },
      ),
      findById: vi.fn((id: string) => Promise.resolve(rows.get(id) ?? null)),
    },
  };
});

import { emitNotification } from '../utils/emit-notification.js';
import { notificationOps } from '../db/ops.js';
import { projectEvents, type ProjectEvent } from '../services/project-events.js';
import type { Notification } from '@devdash/api-types';

/** Capture every notifications:new event fired during `fn()`. */
async function captureEvents(fn: () => Promise<unknown>): Promise<ProjectEvent[]> {
  const captured: ProjectEvent[] = [];
  const listener = (event: ProjectEvent) => {
    if (event.type === 'notifications:new') {
      captured.push(event);
    }
  };
  projectEvents.on('change', listener);
  try {
    await fn();
  } finally {
    projectEvents.removeListener('change', listener);
  }
  return captured;
}

describe('emitNotification chokepoint', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('calls notificationOps.create BEFORE emitting (persistence precedes publish)', async () => {
    const callOrder: string[] = [];
    vi.mocked(notificationOps.create).mockImplementationOnce(((...args: any[]) => {
      callOrder.push('create');
      // Delegate to the real mock-state population so findById works afterward
      const [id, userId, type, title, message] = args;
      (notificationOps.findById as any).mockResolvedValueOnce({
        id, userId, type, title, message,
        read: false,
        dismissed: false,
        metadata: args[5],
        createdAt: new Date('2026-04-11T00:00:00.000Z'),
      });
      return Promise.resolve();
    }) as any);

    const originalEmit = projectEvents.emit.bind(projectEvents);
    const emitSpy = vi.spyOn(projectEvents, 'emit').mockImplementation((...args: any[]) => {
      if (args[0] === 'change' && (args[1] as ProjectEvent).type === 'notifications:new') {
        callOrder.push('emit');
      }
      return originalEmit(args[0], args[1]);
    });

    try {
      await emitNotification({
        userId: 'user-1',
        type: 'task_assigned',
        title: 'Assigned to you',
        metadata: {
          beadId: 'bead-1',
          projectId: 'proj-1',
          assignedBy: 'actor',
        },
      });
    } finally {
      emitSpy.mockRestore();
    }

    expect(callOrder).toEqual(['create', 'emit']);
  });

  it('publishes a notifications:new event carrying the full wire-format notification', async () => {
    const events = await captureEvents(() =>
      emitNotification({
        userId: 'user-1',
        type: 'task_assigned',
        title: 'Assigned to you: Test bead',
        metadata: {
          beadId: 'bead-xyz',
          projectId: 'proj-abc',
          assignedBy: 'actor',
        },
        projectId: 'proj-abc',
      }),
    );

    expect(events).toHaveLength(1);
    const event = events[0]!;
    expect(event.type).toBe('notifications:new');
    expect(event.userId).toBe('user-1');
    expect(event.projectId).toBe('proj-abc');

    const notif = event.notification as Notification;
    expect(notif).toBeTruthy();
    expect(notif.userId).toBe('user-1');
    expect(notif.type).toBe('task_assigned');
    expect(notif.title).toBe('Assigned to you: Test bead');
    expect(notif.read).toBe(false);
    expect(notif.dismissed).toBe(false);
    // Metadata is parsed, not a raw JSON string
    expect(notif.metadata).toEqual({
      beadId: 'bead-xyz',
      projectId: 'proj-abc',
      assignedBy: 'actor',
    });
    // id is generated by the helper and matches the DB row id
    expect(notif.id).toMatch(/^notif-\d+-[a-z0-9]+$/);
    // createdAt is an ISO string (parseable)
    expect(Number.isNaN(Date.parse(notif.createdAt))).toBe(false);
  });

  it('emits an empty string projectId when caller omits it', async () => {
    const events = await captureEvents(() =>
      emitNotification({
        userId: 'user-1',
        type: 'info',
        title: 'System-level notification',
        metadata: { reason: 'boot' },
        // projectId deliberately omitted
      }),
    );

    expect(events).toHaveLength(1);
    expect(events[0]!.projectId).toBe('');
    expect(events[0]!.userId).toBe('user-1');
    // The per-user filter in events.ts routes by userId, so absent projectId
    // doesn't leak — user scoping wins.
  });

  it('persists the row even when SSE publish throws (best-effort)', async () => {
    const emitSpy = vi.spyOn(projectEvents, 'emit').mockImplementationOnce(() => {
      throw new Error('simulated SSE bus failure');
    });

    let id: string;
    try {
      id = await emitNotification({
        userId: 'user-1',
        type: 'agent_complete',
        title: 'Completed despite bus failure',
        metadata: {
          jobId: 'job-test-sse-fail',
          projectId: 'proj-1',
        },
      });
    } finally {
      emitSpy.mockRestore();
    }

    // create() was called even though emit threw
    expect(notificationOps.create).toHaveBeenCalledTimes(1);
    expect(notificationOps.create).toHaveBeenCalledWith(
      id,
      'user-1',
      'agent_complete',
      'Completed despite bus failure',
      null,
      expect.any(String), // metadata JSON
      null, null, null,
    );
  });

  it('stringifies metadata before passing to notificationOps.create', async () => {
    await emitNotification({
      userId: 'user-1',
      type: 'mention',
      title: '@alice mentioned you',
      metadata: {
        beadId: 'bead-1',
        commentId: 'comment-1',
        projectId: 'proj-1',
      },
    });

    expect(notificationOps.create).toHaveBeenCalledTimes(1);
    const metadataArg = vi.mocked(notificationOps.create).mock.calls[0]![5];
    expect(typeof metadataArg).toBe('string');
    expect(JSON.parse(metadataArg as string)).toEqual({
      beadId: 'bead-1',
      commentId: 'comment-1',
      projectId: 'proj-1',
    });
  });

  it('passes orgId / projectId / mentionType through when provided', async () => {
    await emitNotification({
      userId: 'user-1',
      type: 'mention',
      title: '@alice mentioned you',
      metadata: {
        beadId: 'bead-1',
        commentId: 'comment-1',
        projectId: 'proj-1',
      },
      orgId: 'org-1',
      projectId: 'proj-1',
      mentionType: 'direct',
    });

    const call = vi.mocked(notificationOps.create).mock.calls[0]!;
    expect(call[6]).toBe('org-1');       // orgId
    expect(call[7]).toBe('proj-1');      // projectId
    expect(call[8]).toBe('direct');      // mentionType
  });

  it('enforces metadata shape per type at compile time', async () => {
    // This test is really a compile-time assertion wrapped in a runtime smoke
    // test. If MetadataFor<T> ever stops narrowing, the metadata literals
    // below won't match the per-type schemas and tsc will fail.

    await emitNotification({
      userId: 'user-1',
      type: 'agent_complete',
      title: 'Agent succeeded',
      metadata: {
        jobId: 'job-a',
        beadId: 'bead-a',
        projectId: 'proj-1',
        prUrl: 'https://github.com/owner/repo/pull/1',
        commitSha: 'deadbeef',
        branchName: 'feat/test',
      },
    });

    await emitNotification({
      userId: 'user-1',
      type: 'agent_failed',
      title: 'Agent failed',
      metadata: {
        jobId: 'job-b',
        projectId: 'proj-1',
        rescueBranch: 'rescue/job-b',
      },
    });

    await emitNotification({
      userId: 'user-1',
      type: 'task_assigned',
      title: 'Assigned',
      metadata: {
        beadId: 'bead-a',
        projectId: 'proj-1',
        assignedBy: 'actor',
        handoff: true,
      },
    });

    await emitNotification({
      userId: 'user-1',
      type: 'mention',
      title: '@alice mentioned you',
      metadata: {
        beadId: 'bead-a',
        commentId: 'comment-a',
        projectId: 'proj-1',
      },
    });

    expect(notificationOps.create).toHaveBeenCalledTimes(4);
  });

  it('returned id matches the id persisted in the row and the event', async () => {
    const events = await captureEvents(async () => {
      const id = await emitNotification({
        userId: 'user-1',
        type: 'info',
        title: 'id check',
        metadata: {},
      });
      // Capture the id so we can check it against the event below
      (globalThis as any).__lastId = id;
    });

    const returnedId = (globalThis as any).__lastId;
    delete (globalThis as any).__lastId;

    expect(returnedId).toMatch(/^notif-\d+-[a-z0-9]+$/);
    expect(events[0]!.notification!.id).toBe(returnedId);
    expect(vi.mocked(notificationOps.create).mock.calls[0]![0]).toBe(returnedId);
  });
});

