53	  const diffDay = Math.floor(diffHour / 24);
54	
55	  if (diffSec < 60) return 'just now';
56	  if (diffMin < 60) return `${diffMin} minute${diffMin === 1 ? '' : 's'} ago`;
57	  if (diffHour < 24) return `${diffHour} hour${diffHour === 1 ? '' : 's'} ago`;
58	  if (diffDay < 7) return `${diffDay} day${diffDay === 1 ? '' : 's'} ago`;
