import React, { useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import {
  Bell,
  CheckCheck,
  Trash2,
  Filter,
  AlertCircle,
  AtSign,
  CheckCircle2,
  Cpu,
  Info,
  X,
  GitPullRequest,
  GitBranch,
} from 'lucide-react';
import {
  useNotifications,
  useMarkAsRead,
  useMarkAllAsRead,
  useDeleteNotification,
} from '../hooks/useNotifications';
import { useProjects } from '../hooks/useProjects';
import { Card } from '../components/common/Card';
import { Button } from '../components/common/Button';
import type { Notification, NotificationType } from '../types';
import {
  deriveClickTarget,
  deriveSecondaryAction,
  type ClickTarget,
  type ClickTargetContext,
  type SecondaryAction,
} from '../lib/notifications/deriveClickTarget';

const NOTIFICATION_TYPES: { value: NotificationType | 'all'; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'agent_complete', label: 'Agent Complete' },
  { value: 'agent_failed', label: 'Agent Failed' },
  { value: 'task_assigned', label: 'Task Assigned' },
  { value: 'task_completed', label: 'Task Completed' },
  { value: 'mention', label: 'Mention' },
  { value: 'system', label: 'System' },
  { value: 'info', label: 'Info' },
];

function formatDate(dateString: string): string {
  const date = new Date(dateString);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffSec = Math.floor(diffMs / 1000);
  const diffMin = Math.floor(diffSec / 60);
  const diffHour = Math.floor(diffMin / 60);
  const diffDay = Math.floor(diffHour / 24);

  if (diffSec < 60) return 'just now';
  if (diffMin < 60) return `${diffMin} minute${diffMin === 1 ? '' : 's'} ago`;
  if (diffHour < 24) return `${diffHour} hour${diffHour === 1 ? '' : 's'} ago`;
  if (diffDay < 7) return `${diffDay} day${diffDay === 1 ? '' : 's'} ago`;
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined,
  });
}

function getNotificationIcon(type: NotificationType) {
  switch (type) {
    case 'agent_complete':
      return <CheckCircle2 className="w-5 h-5 text-brand-accent" />;
    case 'agent_failed':
      return <AlertCircle className="w-5 h-5 text-brand-danger" />;
    case 'task_assigned':
    case 'task_completed':
      return <Cpu className="w-5 h-5 text-brand-primary" />;
    case 'mention':
      return <AtSign className="w-5 h-5 text-brand-primary" />;
    case 'system':
      return <AlertCircle className="w-5 h-5 text-brand-secondary" />;
    case 'info':
    default:
      return <Info className="w-5 h-5 text-theme-muted" />;
  }
}

function getTypeLabel(type: NotificationType): string {
  const typeConfig = NOTIFICATION_TYPES.find((t) => t.value === type);
  return typeConfig?.label || type;
}

interface NotificationRowProps {
  notification: Notification;
  target: ClickTarget;
  secondary: SecondaryAction | null;
  onMarkAsRead: (id: string) => void;
  onDelete: (id: string) => void;
}

function NotificationRow({
  notification,
  target,
  secondary,
  onMarkAsRead,
  onDelete,
}: NotificationRowProps) {
  // Fire-and-forget mark-read; do NOT await so navigation isn't blocked.
  const handleActivate = () => {
    if (!notification.read) {
      onMarkAsRead(notification.id);
    }
  };

  // Action buttons (mark-read / delete / secondary link) must not trigger the
  // row's primary-link navigation — stop propagation so the wrapping anchor
  // doesn't fire.
  const stop = (e: React.MouseEvent) => e.stopPropagation();

  const rowClass = `block p-4 border-b border-theme-border/50 hover:bg-theme-border/30 transition-colors ${
    !notification.read ? 'bg-brand-primary/5' : ''
  }`;

  const inner = (
    <div className="flex items-start gap-4">
      {/* Icon */}
      <div className="flex-shrink-0 mt-0.5">{getNotificationIcon(notification.type)}</div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <div className="flex items-start justify-between gap-4">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <h3
                className={`text-sm truncate ${
                  !notification.read ? 'font-medium text-theme-text' : 'text-theme-muted'
                }`}
              >
                {notification.title}
              </h3>
              {!notification.read && (
                <span className="w-2 h-2 bg-brand-primary rounded-full flex-shrink-0" />
              )}
            </div>
            {notification.message && (
              <p className="text-sm text-theme-muted mt-1">{notification.message}</p>
            )}
            <div className="flex items-center gap-3 mt-2">
              <span className="text-xs text-theme-muted/70">
                {formatDate(notification.createdAt)}
              </span>
              <span className="text-xs px-2 py-0.5 rounded-full bg-theme-border text-theme-muted">
                {getTypeLabel(notification.type)}
              </span>
            </div>
          </div>

          {/* Actions — each stops propagation so the row-link isn't activated. */}
          <div className="flex items-center gap-1 flex-shrink-0" onClick={stop}>
            {secondary && (
              <a
                href={secondary.href}
                target="_blank"
                rel="noopener noreferrer"
                onClick={(e) => {
                  e.stopPropagation();
                  handleActivate();
                }}
                className="p-1.5 rounded hover:bg-theme-border text-theme-muted hover:text-brand-primary transition-colors"
                title={secondary.label}
                aria-label={secondary.label}
              >
                {secondary.icon === 'pr' ? (
                  <GitPullRequest className="w-4 h-4" />
                ) : (
                  <GitBranch className="w-4 h-4" />
                )}
              </a>
            )}
            {!notification.read && (
              <Button
                variant="ghost"
                size="sm"
                className="p-1.5"
                onClick={(e) => {
                  e.stopPropagation();
                  onMarkAsRead(notification.id);
                }}
                title="Mark as read"
              >
                <CheckCircle2 className="w-4 h-4" />
              </Button>
            )}
            <Button
              variant="ghost"
              size="sm"
              className="p-1.5 text-theme-muted hover:text-brand-danger"
              onClick={(e) => {
                e.stopPropagation();
                onDelete(notification.id);
              }}
              title="Delete"
            >
              <Trash2 className="w-4 h-4" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );

  if (target.kind === 'none') {
    return <div className={rowClass}>{inner}</div>;
  }

  if (target.kind === 'external') {
    return (
      <a
        href={target.href}
        target="_blank"
        rel="noopener noreferrer"
        onClick={handleActivate}
        className={rowClass}
      >
        {inner}
      </a>
    );
  }

  // internal: react-router <Link> supports modifier-key new-tab out of the box.
  return (
    <Link to={target.href} onClick={handleActivate} className={rowClass}>
      {inner}
    </Link>
  );
}

export function Notifications() {
  const [filter, setFilter] = useState<NotificationType | 'all'>('all');
  const [showUnreadOnly, setShowUnreadOnly] = useState(false);

  const { data: notifications, isLoading } = useNotifications();
  const { data: projects } = useProjects();
  const markAsRead = useMarkAsRead();
  const markAllAsRead = useMarkAllAsRead();
  const deleteNotification = useDeleteNotification();

  // Build a projectId -> githubRepo map once so deriveClickTarget can resolve
  // external GitHub URLs (rescue branches, etc).
  const clickCtx = useMemo<ClickTargetContext>(() => {
    const projectRepos: Record<string, string | undefined> = {};
    for (const p of projects ?? []) {
      projectRepos[p.id] = p.githubRepo;
    }
    return { projectRepos };
  }, [projects]);

  const filteredNotifications = useMemo(() => {
    if (!notifications) return [];
    return notifications.filter((n) => {
      if (filter !== 'all' && n.type !== filter) return false;
      if (showUnreadOnly && n.read) return false;
      return true;
    });
  }, [notifications, filter, showUnreadOnly]);

  const unreadCount = notifications?.filter((n) => !n.read).length || 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Bell className="w-6 h-6 text-brand-primary" />
          <h1 className="text-2xl font-bold text-theme-text">Notifications</h1>
          {unreadCount > 0 && (
            <span className="px-2 py-0.5 text-xs font-medium bg-brand-primary text-white rounded-full">
              {unreadCount} unread
            </span>
          )}
        </div>
        {unreadCount > 0 && (
          <Button
            variant="secondary"
            size="sm"
            leftIcon={<CheckCheck className="w-4 h-4" />}
            onClick={() => markAllAsRead.mutate()}
            isLoading={markAllAsRead.isPending}
          >
            Mark all as read
          </Button>
        )}
      </div>

      {/* Filters */}
      <Card className="p-4">
        <div className="flex flex-wrap items-center gap-4">
          {/* Type Filter */}
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-theme-muted" />
            <select
              value={filter}
              onChange={(e) => setFilter(e.target.value as NotificationType | 'all')}
              className="bg-theme-bg border border-theme-border rounded-lg px-3 py-1.5 text-sm text-theme-text focus:outline-none focus:ring-2 focus:ring-brand-primary"
            >
              {NOTIFICATION_TYPES.map((type) => (
                <option key={type.value} value={type.value}>
                  {type.label}
                </option>
              ))}
            </select>
          </div>

          {/* Unread Only Toggle */}
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={showUnreadOnly}
              onChange={(e) => setShowUnreadOnly(e.target.checked)}
              className="w-4 h-4 rounded border-theme-border bg-theme-bg text-brand-primary focus:ring-brand-primary focus:ring-offset-theme-bg"
            />
            <span className="text-sm text-theme-muted">Unread only</span>
          </label>

          {/* Clear Filters */}
          {(filter !== 'all' || showUnreadOnly) && (
            <button
              onClick={() => {
                setFilter('all');
                setShowUnreadOnly(false);
              }}
              className="text-sm text-theme-muted hover:text-theme-text flex items-center gap-1"
            >
              <X className="w-3.5 h-3.5" />
              Clear filters
            </button>
          )}
        </div>
      </Card>

      {/* Notifications List */}
      <Card className="overflow-hidden">
        {isLoading ? (
          <div className="py-12 text-center">
            <div className="animate-spin w-8 h-8 border-2 border-brand-primary border-t-transparent rounded-full mx-auto" />
            <p className="text-theme-muted mt-3">Loading notifications...</p>
          </div>
        ) : filteredNotifications.length === 0 ? (
          <div className="py-12 text-center">
            <Bell className="w-12 h-12 mx-auto text-theme-muted/50 mb-3" />
            <h3 className="text-lg font-medium text-theme-text mb-1">No notifications</h3>
            <p className="text-theme-muted">
              {filter !== 'all' || showUnreadOnly
                ? 'Try adjusting your filters'
                : "You're all caught up!"}
            </p>
          </div>
        ) : (
          <div>
            {filteredNotifications.map((notification) => (
              <NotificationRow
                key={notification.id}
                notification={notification}
                target={deriveClickTarget(notification, clickCtx)}
                secondary={deriveSecondaryAction(notification, clickCtx)}
                onMarkAsRead={(id) => markAsRead.mutate(id)}
                onDelete={(id) => deleteNotification.mutate(id)}
              />
            ))}
          </div>
        )}
      </Card>

      {/* Stats Summary */}
      {notifications && notifications.length > 0 && (
        <div className="text-center text-sm text-theme-muted">
          Showing {filteredNotifications.length} of {notifications.length} notifications
        </div>
      )}
    </div>
  );
}

