import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '../services/api';
import type { ProjectMember, ProjectInvitation, ProjectPermission } from '../types';

interface MembersResponse {
  members: ProjectMember[];
  invitations: ProjectInvitation[];
}

export function useProjectMembers(projectId: string) {
  return useQuery({
    queryKey: ['project-members', projectId],
    queryFn: async () => {
      const response = await api.get<MembersResponse>(`/projects/${projectId}/members`);
      if (!response.success) {
        throw new Error(response.error);
      }
      return response.data!;
    },
    enabled: !!projectId,
  });
}

export function useAddMember(projectId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ email, role = 'member' }: { email: string; role?: 'member' | 'viewer' }) => {
      const response = await api.post<{ type: string; userId?: string; email?: string; role?: string }>(
        `/projects/${projectId}/members`,
        { email, role }
      );
      if (!response.success) {
        throw new Error(response.error);
      }
      return response.data!;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-members', projectId] });
    },
  });
}

export function useUpdateMemberRole(projectId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ userId, role }: { userId: string; role: 'member' | 'viewer' }) => {
      const response = await api.patch<{ success: boolean; role: string }>(
        `/projects/${projectId}/members/${userId}`,
        { role }
      );
      if (!response.success) {
        throw new Error(response.error);
      }
      return response.data!;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-members', projectId] });
    },
  });
}

export function useUpdateMember(projectId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ userId, role, permissions }: { userId: string; role?: 'member' | 'viewer'; permissions?: ProjectPermission[] }) => {
      const body: Record<string, unknown> = {};
      if (permissions) {
        body.permissions = permissions;
      } else if (role) {
        body.role = role;
      }
      const response = await api.patch<{ success: boolean; role: string; permissions: ProjectPermission[] }>(
        `/projects/${projectId}/members/${userId}`,
        body
      );
      if (!response.success) {
        throw new Error(response.error);
      }
      return response.data!;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-members', projectId] });
      queryClient.invalidateQueries({ queryKey: ['projects'] });
    },
  });
}

export function useRemoveMember(projectId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (userId: string) => {
      const response = await api.delete(`/projects/${projectId}/members/${userId}`);
      if (!response.success) {
        throw new Error(response.error);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-members', projectId] });
    },
  });
}

export function useCancelInvitation(projectId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (invitationId: string) => {
      const response = await api.delete(`/projects/${projectId}/invitations/${invitationId}`);
      if (!response.success) {
        throw new Error(response.error);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-members', projectId] });
    },
  });
}

