5	export function useProjects() {
6	  return useQuery({
7	    queryKey: ['projects'],
8	    queryFn: async () => {
9	      const response = await api.get<Project[]>('/projects');
10	      if (!response.success) {
11	        throw new Error(response.error);
12	      }
13	      // Sort by lastAccessedAt (most recent first), fallback to createdAt for never-accessed projects
14	      return response.data!.sort((a, b) => {
15	        const aTime = a.lastAccessedAt ? new Date(a.lastAccessedAt).getTime() : 0;
16	        const bTime = b.lastAccessedAt ? new Date(b.lastAccessedAt).getTime() : 0;
17	        return bTime - aTime;
18	      });
19	    },
20	  });
21	}
