24	  return useQuery({
25	    queryKey: ['projects', id],
26	    queryFn: async () => {
27	      const response = await api.get<Project>(`/projects/${id}`);
28	      if (!response.success) {
29	        throw new Error(response.error);
30	      }
31	      return response.data!;
