function getTypeLabel(type: NotificationType): string {
  const typeConfig = NOTIFICATION_TYPES.find((t) => t.value === type);
  return typeConfig?.label || type;
}

/**
 * Extract a PR number from a GitHub PR URL, e.g.
 *   https://github.com/owner/repo/pull/42  ->  "#42"
 * Returns null if the URL doesn't match the expected shape.
 */
function extractPrNumber(prUrl: string | undefined): string | null {
  if (!prUrl) return null;
  const match = /\/pull\/(\d+)(?:[/?#]|$)/.exec(prUrl);
  return match ? `#${match[1]}` : null;
}

interface PillProps {
  children: React.ReactNode;
  /** Visual variant — defaults to neutral */
  tone?: 'neutral' | 'mono' | 'warn' | 'danger' | 'success';
  icon?: React.ReactNode;
  title?: string;
}

function Pill({ children, tone = 'neutral', icon, title }: PillProps) {
  const toneClass =
    tone === 'warn'
      ? 'bg-amber-500/10 text-amber-500 ring-1 ring-amber-500/20'
      : tone === 'danger'
        ? 'bg-brand-danger/10 text-brand-danger ring-1 ring-brand-danger/20'
        : tone === 'success'
          ? 'bg-brand-accent/10 text-brand-accent ring-1 ring-brand-accent/20'
          : tone === 'mono'
            ? 'bg-theme-border/60 text-theme-text font-mono'
            : 'bg-theme-border/60 text-theme-muted';
  return (
    <span
      className={`inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full ${toneClass}`}
      title={title}
    >
      {icon}
      <span className="truncate max-w-[16rem]">{children}</span>
    </span>
  );
}

interface NotificationMetadataDetailsProps {
  notification: Notification;
  projectsById: Record<string, Project>;
}

/**
 * Type-dispatched metadata summary. Renders a row of pills below the
 * title/message for everything the user might want to see at a glance:
 * which project, which commit, which branch, which PR, whether the event
 * was a handoff / blocked / cancelled / rescued.
 *
 * Returns null for reserved types (task_completed/system/info) that don't
 * have writers today — the shared timestamp + type badge below still
 * renders.
 */
function NotificationMetadataDetails({
  notification,
  projectsById,
}: NotificationMetadataDetailsProps) {
  const md = (notification.metadata ?? {}) as Record<string, unknown>;
  const projectId = typeof md.projectId === 'string' ? (md.projectId as string) : undefined;
  const project = projectId ? projectsById[projectId] : undefined;
  const pills: React.ReactNode[] = [];

  // Project name pill — shown for every type that carries projectId
  if (project) {
    pills.push(
      <Pill key="project" icon={<FolderGit2 className="w-3 h-3" />} title={`Project: ${project.name}`}>
        {project.name}
      </Pill>,
    );
  }

  switch (notification.type) {
    case 'agent_complete': {
      const commitSha = typeof md.commitSha === 'string' ? md.commitSha : undefined;
      const branchName = typeof md.branchName === 'string' ? md.branchName : undefined;
      const prUrl = typeof md.prUrl === 'string' ? md.prUrl : undefined;
      const blocked = md.blocked === true;
      const prNumber = extractPrNumber(prUrl);

      if (blocked) {
        pills.push(
          <Pill key="blocked" tone="warn" title="Agent self-reported blocked">
            BLOCKED
          </Pill>,
        );
      }
      if (prNumber) {
        pills.push(
          <Pill
            key="pr"
            tone="mono"
            icon={<GitPullRequest className="w-3 h-3" />}
            title={prUrl}
          >
            {prNumber}
          </Pill>,
        );
      }
      if (branchName) {
        pills.push(
          <Pill
            key="branch"
            tone="mono"
            icon={<GitBranch className="w-3 h-3" />}
            title={`Branch: ${branchName}`}
          >
            {branchName}
          </Pill>,
        );
      }
      if (commitSha) {
        pills.push(
          <Pill
            key="commit"
            tone="mono"
            icon={<GitCommit className="w-3 h-3" />}
            title={`Commit: ${commitSha}`}
          >
            {commitSha.slice(0, 7)}
          </Pill>,
        );
      }
      // No PR / commit / branch and not blocked → this was a "no changes" run
      if (!blocked && !prNumber && !branchName && !commitSha) {
        pills.push(
          <Pill key="no-changes" title="Agent ran but made no changes">
            no changes
          </Pill>,
        );
      }
      break;
    }

    case 'agent_failed': {
      const cancelled = md.cancelled === true;
      const rescueBranch = typeof md.rescueBranch === 'string' ? md.rescueBranch : undefined;

      if (cancelled) {
        pills.push(
          <Pill key="cancelled" tone="warn" title="Job was manually cancelled">
            CANCELLED
          </Pill>,
        );
      } else {
        pills.push(
          <Pill key="failed" tone="danger" title="Agent job failed">
            FAILED
          </Pill>,
        );
      }
      if (rescueBranch) {
        pills.push(
          <Pill
            key="rescue"
            tone="mono"
            icon={<GitBranch className="w-3 h-3" />}
            title={`Work preserved on ${rescueBranch}`}
          >
            rescue: {rescueBranch}
          </Pill>,
        );
      }
      break;
    }

    case 'task_assigned': {
      const handoff = md.handoff === true;
      if (handoff) {
        pills.push(
          <Pill key="handoff" tone="success" title="Task was handed off with context">
            HANDOFF
          </Pill>,
        );
      }
      break;
    }

    case 'mention':
      // Just the project pill above — the title already says who mentioned
      // whom and where, and the click-through anchors to the comment.
      break;

    case 'task_completed':
    case 'system':
    case 'info':
    default:
      break;
  }

  if (pills.length === 0) return null;

  return <div className="flex flex-wrap items-center gap-2 mt-2">{pills}</div>;
}

