import React, { useState, useEffect } from 'react';
import { useParams, Navigate, useSearchParams, useNavigate } from 'react-router-dom';
import { useProject, useUpdateProject, useInitializeProject, useDeleteProject, useRepoStatus } from '../hooks/useProjects';
import { useRepos } from '../hooks/useRepos';
import { useBeads, useGenerateSuggestions } from '../hooks/useBeads';
import { useProjectEvents } from '../hooks/useProjectEvents';
import { useJobs } from '../hooks/useJobs';
import { useProjectMembers, useAddMember, useRemoveMember, useCancelInvitation, useUpdateMember } from '../hooks/useProjectMembers';
import { Card, CardHeader, CardTitle } from '../components/common/Card';
import { Button } from '../components/common/Button';
import { DispatchPanel } from '../components/agents/TaskAssignment';
import { AgentsTab } from '../components/agents/AgentsTab';
import { BeadsList } from '../components/beads/BeadsList';
import { MemoryPanel } from '../components/memory/MemoryPanel';
import {
  Cpu,
  Bot,
  ListTodo,
  Settings,
  GitBranch,
  Brain,
  ExternalLink,
  Loader2,
  AlertCircle,
  RefreshCw,
  LayoutGrid,
  UserPlus,
  X,
  Clock,
  Users,
  Plus,
  Layers,
  Trash2,
  AlertTriangle,
  Activity,
  Github,
  CheckCircle2,
  Link,
  Lightbulb,
  Sparkles,
} from 'lucide-react';
import { Modal } from '../components/common/Modal';
import { TaskBoard } from '../components/board/TaskBoard';
import { BacklogHealthTab } from '../components/beads/BacklogHealthTab';
import { ActivityFeed } from '../components/activity/ActivityFeed';
import { AnalysisProvider } from '../contexts/AnalysisContext';
import { ProjectSelector } from '../components/layout/ProjectSelector';
import { ChevronDown } from 'lucide-react';
import type { MergeStrategy, Project, ProjectPermission } from '../types';


type Tab = 'dispatch' | 'agents' | 'board' | 'beads' | 'survey' | 'activity' | 'memory' | 'settings';

export function Project() {
  const { id } = useParams<{ id: string }>();
  const { data: project, isLoading, error } = useProject(id!);
  const { data: beads } = useBeads(id!); // unfiltered — for tab count + survey tab
  useProjectEvents(id);
  const [searchParams, setSearchParams] = useSearchParams();
  const tabParam = searchParams.get('tab') as Tab | null;
  const validTabs: Tab[] = ['dispatch', 'agents', 'board', 'beads', 'survey', 'activity', 'memory', 'settings'];
  const [activeTab, setActiveTab] = useState<Tab>(tabParam && validTabs.includes(tabParam) ? tabParam : 'beads');
  const [showNewTask, setShowNewTask] = useState(false);

  // Sync tab from URL query param changes (e.g. sidebar click while already on project)
  useEffect(() => {
    if (tabParam && validTabs.includes(tabParam) && tabParam !== activeTab) {
      setActiveTab(tabParam);
    }
  }, [tabParam]);
  const initializeProject = useInitializeProject();
  // Init status updates come via SSE (beads:changed) + 30s fallback poll — no extra interval needed.

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin w-8 h-8 border-2 border-brand-primary border-t-transparent rounded-full" />
      </div>
    );
  }

  if (error || !project) {
    return <Navigate to="/dashboard" replace />;
  }

  const isOwner = project.role === 'owner';
  const permissions = project.permissions || [];
  const can = {
    manageTasks: isOwner || permissions.includes('manage_tasks'),
    dispatchAgents: isOwner || permissions.includes('dispatch_agents'),
    manageMemory: isOwner || permissions.includes('manage_memory'),
  };
  const canEdit = can.manageTasks || can.dispatchAgents || can.manageMemory;

  const hasRepo = !!project.githubRepo;
  const tabs = [
    { id: 'beads' as Tab, label: 'Tasks', icon: ListTodo, count: beads?.length || 0 },
    { id: 'board' as Tab, label: 'Board', icon: LayoutGrid },
    { id: 'survey' as Tab, label: 'Survey', icon: Layers },
    { id: 'activity' as Tab, label: 'Activity', icon: Activity },
    ...(hasRepo ? [
      { id: 'dispatch' as Tab, label: 'Dispatch', icon: Cpu },
      { id: 'agents' as Tab, label: 'Agents', icon: Bot },
    ] : []),
    { id: 'memory' as Tab, label: 'Memory', icon: Brain },
    { id: 'settings' as Tab, label: 'Settings', icon: Settings },
  ];

  return (
    <AnalysisProvider projectId={id}>
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <ProjectSelector
            renderTrigger={({ isOpen, toggle }) => (
              <button
                onClick={toggle}
                className="flex items-center gap-2 group cursor-pointer"
              >

