import React, { useState, useRef, useEffect, useMemo } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { clsx } from 'clsx';
import { Inspectable } from '../common/Inspectable';
import { Card, CardHeader, CardTitle } from '../common/Card';
import { Button } from '../common/Button';
import { Modal } from '../common/Modal';
import {
  useCreateBead,
  useUpdateBead,
  useBeads,
  useThreeWaySync,
  useSyncState,
  useAcceptSuggestions,
  useDismissSuggestions,
} from '../../hooks/useBeads';
import { useCreateJob, useBacklogHealth, useJobs, ApiError } from '../../hooks/useJobs';
import { api } from '../../services/api';
import { useActiveWorktreeRun } from '../../hooks/useWorktree';
import { useAnalysis } from '../../contexts/AnalysisContext';
import { useToast } from '../../contexts/ToastContext';
import type { Bead, BeadStatus, InitStatus, BacklogHealthReport, WorkerType } from '../../types';
import { Plus, ListTodo, Github, ExternalLink, RefreshCw, CheckCircle, Loader2, Sparkles, Search, X, AlertTriangle, Play, MoreVertical, Check, Trash2, ChevronDown, ChevronRight, Lightbulb } from 'lucide-react';
import { useProjectChat, type ChatAction } from '../../hooks/useProjectChat';
import { ChatActionCard } from './ChatActionCard';
import { useInitializeProject } from '../../hooks/useProjects';
import { BeadsTree } from './BeadsTree';
import { BeadDetailModal } from './BeadDetailModal';
import { CompletionModal } from './CompletionModal';
import { JobTerminal } from '../jobs/JobTerminal';

interface BeadsListProps {
  projectId: string;
  githubRepo?: string;
  initStatus?: InitStatus | null;
  canManageTasks?: boolean;
  canDispatchAgents?: boolean;
  showNewTaskModal?: boolean;
  onNewTaskModalChange?: (open: boolean) => void;
}

type FilterType = 'all' | 'pending' | 'ready' | 'in_progress' | 'completed' | 'blocked' | 'failed' | 'archived';


export function BeadsList({ projectId, githubRepo, initStatus, canManageTasks = true, canDispatchAgents = true, showNewTaskModal, onNewTaskModalChange }: BeadsListProps) {
  const canEdit = canManageTasks || canDispatchAgents;
  const [filter, setFilter] = useState<FilterType>('all');
  const [typeFilter, setTypeFilter] = useState<string>('all');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Fetch beads with server-side filtering (status stays client-side for tab counts)
  const { data: beads = [], isLoading: beadsLoading } = useBeads(projectId, {
    type: typeFilter === 'all' ? undefined : typeFilter,
    priority: priorityFilter === 'all' ? undefined : priorityFilter,
    search: searchTerm || undefined,
  });
  const [showNewBeadInternal, setShowNewBeadInternal] = useState(false);
  const showNewBead = showNewTaskModal ?? showNewBeadInternal;
  const setShowNewBead = onNewTaskModalChange ?? setShowNewBeadInternal;
  const [selectedBead, setSelectedBead] = useState<Bead | null>(null);
  const [selectedBeadForModal, setSelectedBeadForModal] = useState<Bead | null>(null);
  const [selectedLogJobId, setSelectedLogJobId] = useState<string | null>(null);
  const [newBead, setNewBead] = useState({ subject: '', description: '', beadType: 'task' });
  const [syncMessage, setSyncMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [dispatchBead, setDispatchBead] = useState<Bead | null>(null);
  const [dispatchPrompt, setDispatchPrompt] = useState('');
  const [dispatchWorkerType, setDispatchWorkerType] = useState<WorkerType>('e2b');
  const [dispatchError, setDispatchError] = useState<string | null>(null);
  const [showUnanalyzedWarning, setShowUnanalyzedWarning] = useState(false);
  const [showClearBacklogConfirm, setShowClearBacklogConfirm] = useState(false);
  const [actionsMenuOpen, setActionsMenuOpen] = useState(false);
  const [completionBead, setCompletionBead] = useState<Bead | null>(null);
  // AI chat mode state
  const [aiMode, setAiMode] = useState(false);
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'assistant'; content: string }[]>([]);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const chatScrollRef = useRef<HTMLDivElement>(null);
  const isUserScrolledUp = useRef(false);

