/**
 * Extract a PR number from a GitHub PR URL, e.g.
 *   https://github.com/owner/repo/pull/42  ->  "#42"
 * Returns null if the URL doesn't match the expected shape.
 */
function extractPrNumber(prUrl: string | undefined): string | null {
  if (!prUrl) return null;
  const match = /\/pull\/(\d+)(?:[/?#]|$)/.exec(prUrl);
  return match ? `#${match[1]}` : null;
}

interface PillProps {
  children: React.ReactNode;
  /** Visual variant — defaults to neutral */
  tone?: 'neutral' | 'mono' | 'warn' | 'danger' | 'success';
  icon?: React.ReactNode;
  title?: string;
}

function Pill({ children, tone = 'neutral', icon, title }: PillProps) {
  const toneClass =
    tone === 'warn'
      ? 'bg-amber-500/10 text-amber-500 ring-1 ring-amber-500/20'
      : tone === 'danger'
        ? 'bg-brand-danger/10 text-brand-danger ring-1 ring-brand-danger/20'
        : tone === 'success'
          ? 'bg-brand-accent/10 text-brand-accent ring-1 ring-brand-accent/20'
          : tone === 'mono'
            ? 'bg-theme-border/60 text-theme-text font-mono'
            : 'bg-theme-border/60 text-theme-muted';
  return (
    <span
      className={`inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full ${toneClass}`}
      title={title}
    >
      {icon}
      <span className="truncate max-w-[16rem]">{children}</span>
    </span>
  );
}

