/**
 * Extract a PR number from a GitHub PR URL, e.g.
 *   https://github.com/owner/repo/pull/42  ->  "#42"
 * Returns null if the URL doesn't match the expected shape.
 */
function extractPrNumber(prUrl: string | undefined): string | null {
  if (!prUrl) return null;
  const match = /\/pull\/(\d+)(?:[/?#]|$)/.exec(prUrl);
  return match ? `#${match[1]}` : null;
}

/**
 * Normalize a project's githubRepo value to an `owner/repo` slug. The DB
 * stores either a bare slug or a full https URL; accept both, strip a
 * trailing .git, and return null for anything that doesn't have a slash.
 */
function normalizeRepoSlug(repo: string | undefined): string | null {
  if (!repo) return null;
  const slug = repo.replace(/^https?:\/\/github\.com\//, '').replace(/\.git$/, '');
  return slug.includes('/') ? slug : null;
}

interface PillProps {
  children: React.ReactNode;
  /** Visual variant — defaults to neutral */
  tone?: 'neutral' | 'mono' | 'warn' | 'danger' | 'success';
  icon?: React.ReactNode;
  title?: string;
  /**
   * If set, render as an anchor that opens in a new tab. stopPropagation on
   * click so the enclosing notification row's primary <Link> doesn't also
   * fire. Matches the pattern in JobResultSummary for consistency across
   * the app.
   */
  href?: string;
}

function Pill({ children, tone = 'neutral', icon, title, href }: PillProps) {
  const toneClass =
    tone === 'warn'
      ? 'bg-amber-500/10 text-amber-500 ring-1 ring-amber-500/20'
      : tone === 'danger'
        ? 'bg-brand-danger/10 text-brand-danger ring-1 ring-brand-danger/20'
        : tone === 'success'
          ? 'bg-brand-accent/10 text-brand-accent ring-1 ring-brand-accent/20'
          : tone === 'mono'
            ? 'bg-theme-border/60 text-theme-text font-mono'
            : 'bg-theme-border/60 text-theme-muted';
  const baseClass = `inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full ${toneClass}`;
  const inner = (
    <>
      {icon}
      <span className="truncate max-w-[16rem]">{children}</span>
      {href && <ExternalLink className="w-3 h-3 flex-shrink-0" />}
    </>
  );

  if (href) {
    return (
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        onClick={(e) => e.stopPropagation()}
        className={`${baseClass} hover:brightness-125 transition`}
        title={title}
      >
        {inner}
      </a>
    );
  }

  return (
    <span className={baseClass} title={title}>
      {inner}
    </span>
  );
}

