/**
 * Normalize a project's githubRepo value to an `owner/repo` slug. The DB
 * stores either a bare slug or a full https URL; accept both, strip a
 * trailing .git, and return null for anything that doesn't have a slash.
 */
function normalizeRepoSlug(repo: string | undefined): string | null {
  if (!repo) return null;
  const slug = repo.replace(/^https?:\/\/github\.com\//, '').replace(/\.git$/, '');
  return slug.includes('/') ? slug : null;
}

