function NotificationMetadataDetails({
  notification,
  projectsById,
}: NotificationMetadataDetailsProps) {
  const md = (notification.metadata ?? {}) as Record<string, unknown>;
  const projectId = typeof md.projectId === 'string' ? (md.projectId as string) : undefined;
  const project = projectId ? projectsById[projectId] : undefined;
  const pills: React.ReactNode[] = [];

  // Project name pill — shown for every type that carries projectId
  if (project) {
    pills.push(
      <Pill key="project" icon={<FolderGit2 className="w-3 h-3" />} title={`Project: ${project.name}`}>
        {project.name}
      </Pill>,
    );
  }

  switch (notification.type) {
    case 'agent_complete': {
      const commitSha = typeof md.commitSha === 'string' ? md.commitSha : undefined;
      const branchName = typeof md.branchName === 'string' ? md.branchName : undefined;
      const prUrl = typeof md.prUrl === 'string' ? md.prUrl : undefined;
      const blocked = md.blocked === true;
      const prNumber = extractPrNumber(prUrl);

      if (blocked) {
        pills.push(
          <Pill key="blocked" tone="warn" title="Agent self-reported blocked">
            BLOCKED
          </Pill>,
        );
      }
      if (prNumber) {
        pills.push(
          <Pill
            key="pr"
            tone="mono"
            icon={<GitPullRequest className="w-3 h-3" />}
            title={prUrl}
          >
            {prNumber}
          </Pill>,
        );
      }
      if (branchName) {
        pills.push(
          <Pill
            key="branch"
            tone="mono"
            icon={<GitBranch className="w-3 h-3" />}
            title={`Branch: ${branchName}`}
          >
            {branchName}
          </Pill>,
        );
      }
      if (commitSha) {
        pills.push(
          <Pill
            key="commit"
            tone="mono"
            icon={<GitCommit className="w-3 h-3" />}
            title={`Commit: ${commitSha}`}
          >
            {commitSha.slice(0, 7)}
          </Pill>,
        );
      }
      // No PR / commit / branch and not blocked → this was a "no changes" run
      if (!blocked && !prNumber && !branchName && !commitSha) {
        pills.push(
          <Pill key="no-changes" title="Agent ran but made no changes">
            no changes
          </Pill>,
        );
      }
      break;
    }

    case 'agent_failed': {
      const cancelled = md.cancelled === true;
      const rescueBranch = typeof md.rescueBranch === 'string' ? md.rescueBranch : undefined;

      if (cancelled) {
        pills.push(
          <Pill key="cancelled" tone="warn" title="Job was manually cancelled">
            CANCELLED
          </Pill>,
        );
      } else {
        pills.push(
          <Pill key="failed" tone="danger" title="Agent job failed">
            FAILED
          </Pill>,
        );
      }
      if (rescueBranch) {
        pills.push(
          <Pill
            key="rescue"
            tone="mono"
            icon={<GitBranch className="w-3 h-3" />}
            title={`Work preserved on ${rescueBranch}`}
          >
            rescue: {rescueBranch}
          </Pill>,
        );
      }
      break;
    }

