input.old_string:
// Deep-link from notification click-through: open the requested bead as
// soon as the beads list finishes loading. If the target isn't in the
// currently-filtered list (user had a type/priority/search filter set),
// clear those filters so the server refetches with the full list and the
// effect re-fires.
useEffect(() => {
  if (!initialBeadId) return;
  if (beadsLoading) return;
  if (handledInitialBeadIdRef.current === initialBeadId) return;

  const target = beads.find((b) => b.id === initialBeadId);
  if (target) {
    setSelectedBeadForModal(target);
    handledInitialBeadIdRef.current = initialBeadId;
    return;
  }

  // Target isn't in the filtered results — clear filters so it can be
  // found on the next render. Don't mark as handled yet; we want the
  // effect to re-fire after the refetch.
  if (typeFilter !== 'all' || priorityFilter !== 'all' || searchTerm !== '') {
    setTypeFilter('all');
    setPriorityFilter('all');
    setSearchTerm('');
    return;
  }

  // No filters and still not found — the bead doesn't exist in this
  // project (deleted, wrong project, etc.). Mark as handled so we don't
  // retry forever.
  handledInitialBeadIdRef.current = initialBeadId;
}, [initialBeadId, beadsLoading, beads, typeFilter, priorityFilter, searchTerm]);

input.new_string:
// Deep-link from notification click-through: open the requested bead as
// soon as the single-bead fetch resolves. Independent of the paginated
// useBeads list so it works even when the target is past page 1 or the
// user has filters set.
useEffect(() => {
  if (!initialBeadId) return;
  if (!targetBead) return;
  if (handledInitialBeadIdRef.current === initialBeadId) return;
  setSelectedBeadForModal(targetBead);
  handledInitialBeadIdRef.current = initialBeadId;
}, [initialBeadId, targetBead]);

