import { z } from 'zod/v4';
import { NotificationType } from './enums.js';

// =============================================================================
// Per-type metadata shapes
//
// Source of truth for what each notification type is allowed to carry in its
// `metadata` field. See server/docs/notifications-contract.md for the human
// documentation; the schemas below are what the type system enforces.
//
// Creation sites should go through the `emitNotification()` helper in
// server/src/utils/emit-notification.ts — it uses `MetadataFor<T>` so TS
// narrows the metadata shape based on the supplied `type`.
// =============================================================================

/** agent_complete — job finished (happy path, blocked, or no-changes variants) */
export const AgentCompleteMetadata = z.object({
  jobId: z.string(),
  beadId: z.string().optional(),
