/**
 * Shared enum schemas — single source of truth for all domain enumerations.
 * Route schemas compose from these; client types derive via z.infer<>.
 */
import { z } from 'zod/v4';

// --- Bead ---
export const BeadStatus = z.enum([
  'pending', 'ready', 'in_progress', 'completed', 'blocked', 'failed', 'archived',
]);
export type BeadStatus = z.infer<typeof BeadStatus>;

export const BeadType = z.enum([
  'task', 'bug', 'feature', 'enhancement', 'thought', 'chore',
]);
export type BeadType = z.infer<typeof BeadType>;

// --- Job ---
export const JobStatus = z.enum([
  'queued', 'running', 'completed', 'failed', 'cancelled',
]);
export type JobStatus = z.infer<typeof JobStatus>;

export const JobType = z.enum(['execution', 'analysis', 'audit']);
export type JobType = z.infer<typeof JobType>;

export const WorkerType = z.enum(['docker', 'e2b', 'railway']);
export type WorkerType = z.infer<typeof WorkerType>;

// --- Project ---
export const AIProvider = z.enum(['claude', 'openai', 'openrouter']);
export type AIProvider = z.infer<typeof AIProvider>;

export const MergeStrategy = z.enum(['pr', 'direct']);
export type MergeStrategy = z.infer<typeof MergeStrategy>;

export const ProjectRole = z.enum(['owner', 'member', 'viewer', 'custom']);
