export const ProjectPermission = z.enum([
  'manage_tasks', 'dispatch_agents', 'manage_memory',
]);
export type ProjectPermission = z.infer<typeof ProjectPermission>;

export const InitStatus = z.enum(['pending', 'running', 'completed', 'failed']);
