import { z } from 'zod/v4';
import { NotificationType } from './enums.js';

// =============================================================================
// Per-type metadata shapes
//
// Source of truth for what each notification type is allowed to carry in its
// `metadata` field. See server/docs/notifications-contract.md for the human
// documentation; the schemas below are what the type system enforces.
//
// Creation sites should go through the `emitNotification()` helper in
// server/src/utils/emit-notification.ts — it uses `MetadataFor<T>` so TS
// narrows the metadata shape based on the supplied `type`.
// =============================================================================

/**
 * agent_complete — job finished (happy path, blocked, or no-changes variants).
 *
 * `projectId` is REQUIRED. Notifications without it would degrade to /dashboard
 * in deriveClickTarget — see dd `0cf7f8e0` for the prod incident where ~141 old
 * notifications were created without projectId before the contract overhaul
 * landed. Keep this required so any future writer omitting it fails at tsc.
 */
export const AgentCompleteMetadata = z.object({
  jobId: z.string(),
  projectId: z.string(),
  beadId: z.string().optional(),
  prUrl: z.string().optional(),
  commitSha: z.string().optional(),
  branchName: z.string().optional(),
  blocked: z.boolean().optional(),
});
export type AgentCompleteMetadata = z.infer<typeof AgentCompleteMetadata>;

/**
 * agent_failed — job errored, was rescued, or was cancelled.
 *
 * `projectId` is REQUIRED. See AgentCompleteMetadata above for why.
 */
export const AgentFailedMetadata = z.object({
  jobId: z.string(),
  projectId: z.string(),
  beadId: z.string().optional(),
  rescueBranch: z.string().optional(),
  cancelled: z.boolean().optional(),
});
export type AgentFailedMetadata = z.infer<typeof AgentFailedMetadata>;

/** task_assigned — bead assignment or handoff */
export const TaskAssignedMetadata = z.object({
  beadId: z.string(),
  projectId: z.string(),
  assignedBy: z.string().optional(),
  handoff: z.boolean().optional(),
});
export type TaskAssignedMetadata = z.infer<typeof TaskAssignedMetadata>;

/** task_status_changed — bead transitioned between statuses */
export const TaskStatusChangedMetadata = z.object({
  beadId: z.string(),
  projectId: z.string(),
  fromStatus: z.string(),
  toStatus: z.string(),
  changedBy: z.string(),
});
export type TaskStatusChangedMetadata = z.infer<typeof TaskStatusChangedMetadata>;

/** comment_added — someone commented on a bead you own or are assigned to */
export const CommentAddedMetadata = z.object({
  beadId: z.string(),
  commentId: z.string(),
  projectId: z.string(),
  commentedBy: z.string(),
});
export type CommentAddedMetadata = z.infer<typeof CommentAddedMetadata>;

/** dependency_resolved — a bead you were blocked-by just completed */
export const DependencyResolvedMetadata = z.object({
  beadId: z.string(),
  resolvedBeadId: z.string(),
  projectId: z.string(),
});
export type DependencyResolvedMetadata = z.infer<typeof DependencyResolvedMetadata>;

/** priority_changed — someone changed priority on a bead you're assigned to */
export const PriorityChangedMetadata = z.object({
  beadId: z.string(),
  projectId: z.string(),
  fromPriority: z.number(),
  toPriority: z.number(),
  changedBy: z.string(),
});
export type PriorityChangedMetadata = z.infer<typeof PriorityChangedMetadata>;

/** member_joined — someone joined your project */
export const MemberJoinedMetadata = z.object({
  projectId: z.string(),
  memberId: z.string(),
  memberName: z.string().optional(),
  role: z.string(),
});
export type MemberJoinedMetadata = z.infer<typeof MemberJoinedMetadata>;

/** member_left — someone left or was removed from your project */
export const MemberLeftMetadata = z.object({
  projectId: z.string(),
  memberId: z.string(),
  memberName: z.string().optional(),
});
export type MemberLeftMetadata = z.infer<typeof MemberLeftMetadata>;

/** mention — someone @-mentioned this user in a bead comment */
export const MentionMetadata = z.object({
  beadId: z.string(),
  commentId: z.string(),
  projectId: z.string(),
});
export type MentionMetadata = z.infer<typeof MentionMetadata>;

/** system / info — freeform; no contract enforced */
export const FreeformMetadata = z.record(z.string(), z.unknown());
export type FreeformMetadata = z.infer<typeof FreeformMetadata>;

// =============================================================================
// Type-level map: NotificationType -> metadata shape
//
// Use `MetadataFor<'agent_complete'>` at call sites to get compile-time
// narrowing. The outer Notification row carries the `type` discriminator,
// not the metadata blob itself, so we index by type rather than build a
// true discriminated union.
// =============================================================================

export type NotificationMetadataByType = {
  agent_complete: AgentCompleteMetadata;
  agent_failed: AgentFailedMetadata;
  task_status_changed: TaskStatusChangedMetadata;
  comment_added: CommentAddedMetadata;
  dependency_resolved: DependencyResolvedMetadata;
  task_assigned: TaskAssignedMetadata;
  priority_changed: PriorityChangedMetadata;
  mention: MentionMetadata;
  member_joined: MemberJoinedMetadata;
  member_left: MemberLeftMetadata;
  system: FreeformMetadata;
  info: FreeformMetadata;
};

export type MetadataFor<T extends z.infer<typeof NotificationType>> =
  NotificationMetadataByType[T];

/**
 * Zod validator for a notification's metadata given its type.
 * Used by SSE payload validation and any future boundary-check paths.
 */
export const metadataSchemaFor = (type: z.infer<typeof NotificationType>) => {
  switch (type) {
    case 'agent_complete': return AgentCompleteMetadata;
    case 'agent_failed': return AgentFailedMetadata;
    case 'task_assigned': return TaskAssignedMetadata;
    case 'task_completed': return TaskCompletedMetadata;
    case 'mention': return MentionMetadata;
    case 'system':
    case 'info':
    default:
      return FreeformMetadata;
  }
};

