import React from 'react';
import { useOutletContext } from 'react-router-dom';
import { clsx } from 'clsx';
import {
  AtSign,
  CheckCircle,
  XCircle,
  UserPlus,
  Info,
  Bell,
} from 'lucide-react';
import { useNotifications, useMarkAsRead, useMarkAllAsRead } from '../../../hooks/useNotifications';
import { Button } from '../../common/Button';
import type { NotificationType } from '../../../types';

const typeIcons: Record<NotificationType, React.ElementType> = {
  agent_complete: CheckCircle,
  agent_failed: XCircle,
  task_assigned: UserPlus,
  task_completed: CheckCircle,
  mention: AtSign,
  system: Info,
  info: Bell,
};

const typeColors: Record<NotificationType, string> = {
  agent_complete: 'text-brand-secondary',
  agent_failed: 'text-brand-danger',
  task_assigned: 'text-brand-primary',
  task_completed: 'text-brand-secondary',
  mention: 'text-brand-primary',
  system: 'text-theme-muted',
  info: 'text-brand-primary',
};

function timeAgo(dateStr: string): string {
  const diff = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

export function MobileActivityScreen() {
  const { data: notifications, isLoading } = useNotifications();
  const markAsRead = useMarkAsRead();
  const markAllAsRead = useMarkAllAsRead();

  const unreadCount = notifications?.filter((n) => !n.read).length || 0;

  return (
    <div className="flex flex-col h-full">
      {/* Header with mark all read */}
      <div className="flex items-center justify-between px-4 pt-3 pb-2 sticky top-0 bg-theme-bg z-10">
        <h2 className="text-sm font-semibold text-theme-text">
          Activity {unreadCount > 0 && <span className="text-brand-primary">({unreadCount})</span>}
        </h2>
        {unreadCount > 0 && (
          <Button
            size="sm"
            variant="ghost"
            onClick={() => markAllAsRead.mutate()}
            isLoading={markAllAsRead.isPending}
          >
            Mark all read
          </Button>
        )}
      </div>

      {/* Notification list */}
      <div className="flex-1 overflow-y-auto">
        {isLoading ? (
          <div className="flex justify-center py-12">
            <div className="animate-spin w-6 h-6 border-2 border-brand-primary border-t-transparent rounded-full" />
          </div>
        ) : !notifications || notifications.length === 0 ? (
          <div className="text-center py-12">
            <Bell className="w-10 h-10 text-theme-muted mx-auto mb-3 opacity-50" />
            <p className="text-sm text-theme-muted">No notifications yet</p>
          </div>
        ) : (
          notifications.map((n) => {
            const Icon = typeIcons[n.type] || Bell;
            const color = typeColors[n.type] || 'text-theme-muted';
            return (
              <button
                key={n.id}
                onClick={() => {
                  if (!n.read) markAsRead.mutate(n.id);
                }}
                className={clsx(
                  'w-full flex items-start gap-3 px-4 py-3 border-b border-theme-border/50 text-left transition-colors',
                  !n.read && 'bg-brand-primary/5'
                )}
              >
                <Icon className={clsx('w-5 h-5 mt-0.5 flex-shrink-0', color)} />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <p className={clsx('text-sm font-medium flex-1 truncate', !n.read ? 'text-theme-text' : 'text-theme-muted')}>
                      {n.title}
                    </p>
                    {!n.read && (
                      <span className="w-2 h-2 rounded-full bg-brand-primary flex-shrink-0" />
                    )}
                  </div>
                  {n.message && (
                    <p className="text-xs text-theme-muted line-clamp-2 mt-0.5">{n.message}</p>
                  )}
                  <p className="text-[10px] text-theme-muted mt-1">{timeAgo(n.createdAt)}</p>
                </div>
              </button>
            );
          })
        )}
      </div>
    </div>
  );
}

