141	
142	  // 3. Cascade: unblock dependents via `blocks` array (batch fetch to avoid N+1)
143	  const blocksIds: string[] = bead.blocks ? JSON.parse(bead.blocks) : [];
144	  if (blocksIds.length > 0) {
145	    const deps = await pgDb.execute(sql`SELECT * FROM beads WHERE id IN (${sql.join(blocksIds.map(id => sql`${id}`), sql`, `)})`) as any;
146	    const depsRows = deps.rows as any[];
147	
148	    for (const dep of depsRows) {
149	      if (dep.status !== 'blocked' && dep.status !== 'pending') continue;
150	
151	      const depBlockedBy: string[] = dep.blockedBy ? JSON.parse(dep.blockedBy) : [];
152	      const remaining = depBlockedBy.filter((id: string) => id !== beadId);
153	
154	      // Update blocked_by array
155	      await beadOps.updateBlockedBy(JSON.stringify(remaining), dep.id);
156	
157	      // If no more blockers, transition blocked → pending
158	      if (remaining.length === 0 && dep.status === 'blocked') {
159	        await beadOps.updateStatus('pending', dep.id);
160	        changed.push(dep.id);
161	        logStatusChange(dep.id, 'blocked', 'pending', dep.subject, 'system');
162	      }
163	    }
164	  }
165	
166	  // 4. Parent auto-complete: if all siblings are completed, complete the parent
