router.post('/:beadId/comments', validate({ body: CreateCommentBody }), async (req, res) => {
  try {
    const beadId = req.params.beadId as string;
    const { projectId, content, metadata } = req.body as CreateCommentBody;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'manage_tasks');
    if (!project) {
      return res.status(403).json({ error: 'manage_tasks permission required' });
    }

    const bead = await beadOps.findById(beadId) as any;
    if (!bead || bead.projectId !== projectId) {
      return res.status(404).json({ error: 'Bead not found' });
    }

    const id = uuidv4();
    await beadCommentOps.create(
      id,
      beadId,
      projectId,
      userId,
      'user',
      content,
      metadata ? JSON.stringify(metadata) : null
    );

    const row = await beadCommentOps.findById(id) as any;
    const user = await userOps.findById(userId) as any;
    const author = user ? { id: user.id, displayName: user.displayName, avatarUrl: user.avatarUrl } : null;

    logActivity({
      projectId,
      actorId: userId,
      actorType: 'user',
      action: 'comment.created',
      targetType: 'bead',
      targetId: beadId,
      metadata: { commentId: id, beadSubject: bead.subject },
    });

    // Generate @mention notifications
    try {
      const usernames = parseMentions(content);
      if (usernames.length > 0) {
        const mentionedUserIds = await resolveMentionedUsers(usernames, projectId);
        const actorUser = await userOps.findById(userId) as any;
        const actorName = actorUser?.displayName || actorUser?.username || 'Someone';
        const proj = await projectOps.findById(projectId) as any;

        for (const mentionedId of mentionedUserIds) {
          if (mentionedId === userId) continue; // Don't notify yourself
          await emitNotification({
            userId: mentionedId,
            type: 'mention',
            title: `@${actorName} mentioned you in ${bead.subject}`,
            message: content.length > 200 ? content.slice(0, 200) + '...' : content,
            metadata: { beadId, commentId: id, projectId },
            orgId: proj?.orgId || null,
            projectId,
            mentionType: 'direct',
          });
        }
      }
    } catch (mentionErr) {
      console.warn('[Comments] Error generating mention notifications:', mentionErr);
    }

    projectEvents.emit('change', { type: 'comments:changed', projectId });
    res.status(201).json(formatComment(row, author));
  } catch (error) {
    console.error('Error creating comment:', error);
    res.status(500).json({ error: 'Failed to create comment' });
  }
});

