  const invitations = await projectInvitationOps.findByEmail(user.email) as any[];
  for (const inv of invitations) {
    await projectMemberOps.add(inv.projectId, user.id, inv.role || 'member', inv.permissions || null);
    await projectInvitationOps.delete(inv.id);
    redeemedProjectIds.push(inv.projectId);

    // Notify the project owner that the invited user joined
    try {
      const invProject = await projectOps.findById(inv.projectId) as any;
      if (invProject?.userId && invProject.userId !== user.id) {
        await emitNotification({
          userId: invProject.userId,
          type: 'member_joined',
          title: `${user.displayName || user.email} joined ${invProject.name}`,
          metadata: {
            projectId: inv.projectId,
            memberId: user.id,
            memberName: user.displayName || user.email,
            role: inv.role || 'member',
          },
        });
      }
    } catch (notifErr) {
      console.warn('[Auth] Failed to send member_joined notification:', notifErr);
    }
  }
  if (invitations.length > 0) {
    console.log(`[Auth] Redeemed ${invitations.length} invitation(s) for ${user.email}`);
  }
} catch (err) {
  console.error('[Auth] Error redeeming invitations:', err);
